"""CloudFormation Template Generator for AgentCore Flows.

Converts a DeployRequest (workflow definition from the frontend) into a
complete CloudFormation template bundle using native AWS::BedrockAgentCore::*
resource types wherever they exist.

Four Custom Resources are emitted, all served by the single cfn-provider
Lambda in ``cfn_provider/handler.py``, because no native CFN type covers them:

- ``Custom::AgentCodePackage`` — merges the agent code with a prebuilt
  dependency bundle and uploads the final code.zip at deploy time. Always
  present.
- ``Custom::RuntimeLogGroup`` — applies the stack's retention period and
  customer-managed key to the log groups AgentCore creates for each runtime.
  ``AWS::BedrockAgentCore::Runtime`` has no logging properties, and the service
  creates the groups itself, so nothing declared can reach them. One per
  runtime, always present.
- ``Custom::OAuth2CredentialProvider`` — creates the AgentCore OAuth2
  credential provider that authenticates the Gateway to an MCP Server
  Runtime. Emitted only on the MCP-server path.
- ``Custom::AgentCorePolicy`` — creates the Cedar policy attached to a
  PolicyEngine. Emitted only when a policy is configured.

Keep this list in sync with the handler dispatch in
``cfn_provider/handler.py`` and with the architecture note in the generated
README (``_generate_readme``). All three have drifted before.

The generated bundle includes:
- template.yaml — CloudFormation template
- agent-code/agent.py — Pre-generated agent code (env-var driven)
- cfn-provider.zip — Custom Resource Lambda (code packaging, runtime log group
  governance, OAuth2 credential provider, Cedar policy)
- tool-lambdas.zip — Gateway tool Lambda functions (if applicable)
- custom-tools.zip — Customer tool Lambda functions (if applicable)
- build-dependency-bundle.sh — Reproducible aarch64 dependency builder
- deploy.sh — One-command deployment script
- teardown.sh — Stack deletion script
- README.md — Documentation

The large dependency ZIP is deliberately not nested in every export. Instead,
``deploy.sh`` checks the target bucket and, when it is absent, runs the included
``build-dependency-bundle.sh`` recipe and uploads it under
``DependencyBundleKey``. An offline recipient can vendor that generated ZIP
beside the scripts or pre-stage it in S3. See the README section generated by
``_generate_readme``.
"""

