logger = logging.getLogger(__name__)


class _NoAliasDumper(yaml.SafeDumper):
    """A dumper that repeats a shared node instead of aliasing it.

    CloudFormation rejects YAML anchors and aliases outright:
    ``Template error: YAML aliases are not allowed in CloudFormation templates``,
    at CreateChangeSet, before it looks at a single resource. PyYAML emits them
    whenever the same object is reachable from two places in the tree, which is easy
    to do by accident with a module-level constant like a ``{"Ref": ...}`` and
    impossible to see afterwards — the emitted template still round-trips through
    ``yaml.safe_load`` to exactly the right structure, and reads correctly to a human.

    So this is a backstop, not the fix: the shared objects are also gone (see
    ``_customer_key_ref``). It is here because the failure is total, silent until a
    real deploy, and one careless shared dict away at any time.
    """

    def ignore_aliases(self, data):  # noqa: ANN001, ANN201 - PyYAML's own signature
        return True


def _dump_template(template: dict) -> str:
    return yaml.dump(
        template,
        Dumper=_NoAliasDumper,
        default_flow_style=False,
        sort_keys=False,
        allow_unicode=True,
    )


# ---------------------------------------------------------------------------
# Governance tagging  (DeployRequest.resource_tags / tag_profile)
# ---------------------------------------------------------------------------

#: Which property carries tags on each type the emitted template contains, and in which
#: of CloudFormation's two incompatible shapes. NOT guessed and not inferred from the
#: property name: read out of cfn-lint's bundled provider schemas
#: (``cfnlint.schema.PROVIDER_SCHEMA_MANAGER.get_resource_schema``), which are the
#: registry schemas CloudFormation itself validates against. Getting a shape wrong here
#: does not fail the export -- it produces a template that fails at CreateChangeSet, in
#: the customer's account, on a property they never typed.
#:
#: The distinction is real and not cosmetic:
#:   * Cognito uses ``UserPoolTags``, a map, under a DIFFERENT property name
#:   * IAM, Lambda, Logs and S3Vectors use ``Tags`` as a LIST -> [{"Key": k, "Value": v}]
#:   * AgentCore is NOT internally consistent: ``Gateway``, ``Memory``, ``Runtime`` and
#:     ``RuntimeEndpoint`` take a MAP, while ``PolicyEngine`` and
#:     ``OnlineEvaluationConfig`` -- same service, same namespace -- take a LIST. There is
#:     no rule to derive here. Every row below was read out of that type's own schema.
#:
#: THIS TABLE MUST COVER EVERY TYPE ``generate()`` CAN EMIT, not every type it happens to
#: emit for a simple canvas. The first version covered 9 of the 26 and looked complete,
#: because the tests exercised one component at a time: ``GatewayTarget`` only appears when
#: a gateway and an MCP server are BOTH enabled, so the fail-closed branch in
#: ``_apply_resource_tags`` turned that combination into an HTTP 400 for any caller
#: supplying tags. Found by linting a live export per component combination, not by a unit
#: test. ``test_every_emitted_type_is_classified`` now parametrizes the combinations too.
_TAG_PROPERTY: dict[str, tuple[str, str]] = {
    "AWS::BedrockAgentCore::Gateway": ("Tags", "map"),
    "AWS::BedrockAgentCore::Memory": ("Tags", "map"),
    "AWS::BedrockAgentCore::Runtime": ("Tags", "map"),
    "AWS::BedrockAgentCore::RuntimeEndpoint": ("Tags", "map"),
    "AWS::BedrockAgentCore::OnlineEvaluationConfig": ("Tags", "list"),
    "AWS::BedrockAgentCore::PolicyEngine": ("Tags", "list"),
    "AWS::Bedrock::Guardrail": ("Tags", "list"),
    "AWS::Bedrock::KnowledgeBase": ("Tags", "map"),
    "AWS::Cognito::UserPool": ("UserPoolTags", "map"),
    "AWS::IAM::Role": ("Tags", "list"),
    "AWS::Lambda::Function": ("Tags", "list"),
    "AWS::Logs::LogGroup": ("Tags", "list"),
    "AWS::S3Vectors::Index": ("Tags", "list"),
    "AWS::S3Vectors::VectorBucket": ("Tags", "list"),
}

#: Types the template emits that carry no tag property at all, each with the reason, so
#: an untagged resource is a recorded decision rather than an oversight. Verified against
#: the same schemas: adding ``Tags`` to any of these is a template that will not deploy.
#:
#: ``AWS::Lambda::EventInvokeConfig`` is here because of a near-miss worth recording: a
#: ``"tag" in name.lower()`` sweep of its properties "found" a tag property, which was
#: ``MaximumEventAgeInSeconds`` -- "evenTAGe". The schema has no tag support.
_UNTAGGABLE: dict[str, str] = {
    "AWS::Cognito::UserPoolClient": "no tag property in the registry schema; the pool it belongs to carries the tags",
    "AWS::Cognito::UserPoolDomain": "no tag property in the registry schema",
    "AWS::Cognito::UserPoolResourceServer": "no tag property in the registry schema",
    "AWS::Bedrock::DataSource": "no tag property in the registry schema; the knowledge base carries the tags",
    "AWS::Bedrock::GuardrailVersion": "no tag property in the registry schema; a version pointer at the guardrail, which is tagged",
    "AWS::BedrockAgentCore::GatewayTarget": "no tag property in the registry schema; the gateway it attaches to carries the tags",
    "AWS::Lambda::EventInvokeConfig": "a configuration overlay on a function, not a taggable resource",
    "AWS::Lambda::Permission": "a policy statement on a function, not a taggable resource",
}

# A Custom Resource is only the CloudFormation invocation surface. Three handlers
# create or govern real taggable resources, so their effective tags have to cross
# that boundary explicitly. The value is the tightest tag-count limit on the sink:
# S3 object tags are capped at 10; the OAuth provider and CloudWatch Logs accept 50.
_CUSTOM_RESOURCE_TAG_LIMITS: dict[str, int] = {
    "Custom::AgentCodePackage": 10,
    "Custom::OAuth2CredentialProvider": 50,
    "Custom::RuntimeLogGroup": 50,
}

# AgentCore Policy children do not support tags. Their owning PolicyEngine does, and
# is tagged by the native-resource pass above. Keep this explicit so the exception
# cannot be mistaken for the old blanket "skip every Custom::*" behavior.
_CUSTOM_RESOURCE_TAG_COVERED_BY: dict[str, str] = {
    "Custom::AgentCorePolicy": "AWS::BedrockAgentCore::PolicyEngine",
}

#: The tag character class, the 128/256 length bounds, the reserved-prefix rule and the
#: credential-key refusal now live in ``services/resource_tagging`` so the live deploy path
#: runs the same ones. A third copy exists in ``services/cfn_provider/handler.py`` and has to:
#: that module is the code we ship INTO the customer's account, where this package is not
#: importable. Three copies would be two too many; two is the process boundary.


def _validated_tags(resource_tags: dict | None) -> dict[str, str]:
    """Normalize and validate the caller's tag set, or refuse the export.

    Refuses rather than silently dropping an unusable tag, for the same reason the
    field guard refuses: a customer who asked for a cost-allocation tag and got a
    stack without one has no way to find out except an audit months later.

    The rules themselves now live in ``services/resource_tagging`` because the LIVE deploy
    path needs exactly the same ones and had none: it applied governance tags to the runtime
    exec role with no validation at all, so a key designating credential material was written
    verbatim onto a real IAM role while this function refused the identical export. Delegating
    rather than duplicating is what stops the two paths drifting on what a legal tag is. The
    message text is unchanged -- ``GovernanceTagError`` carries it and is re-raised here as
    ``CfnExportUnsupportedError`` so every existing caller and assertion still sees that type.
    """
    from app.services.resource_tagging import (  # noqa: PLC0415
        GovernanceTagError,
        validated_governance_tags,
    )

    try:
        return validated_governance_tags(resource_tags)
    except GovernanceTagError as exc:
        raise CfnExportUnsupportedError(str(exc)) from exc


def _apply_resource_tags(template: dict, resource_tags: dict | None) -> None:
    """Write the caller's governance tags onto every taggable emitted resource.

    WHY THIS IS EMITTED RATHER THAN REFUSED. ``resource_tags`` and ``tag_profile`` were
    both in the set of fields the export accepted and then discarded (see
    :func:`_reject_what_the_export_cannot_express`). Refusing them would have been
    honest but wrong: ``ResourceTagFields.tsx`` resolves a tag value from the user's
    input, then the selected profile, then the tag policy's ``default_value``, so any
    organisation that sets a default on a tag policy would have had EVERY CloudFormation
    export turned into a 400. Measured on the live stack: the three seeded policies
    (``platform:application``, ``platform:group``, ``platform:owner``) all have
    ``default_value: null`` and no profiles exist, so a default install sends nothing --
    but a bank that fills those defaults in is exactly the caller who needs the export.

    Tags are also cheap to express correctly, which the other eight dropped fields are
    not. So these two get the real fix and the rest keep the refusal.

    Existing tags on a resource win: the generator already sets its own tags in places,
    and a caller's governance tag must not overwrite something the template depends on.
    """
    tags = _validated_tags(resource_tags)
    if not tags:
        return

    resources = template.get("Resources") or {}
    unknown: dict[str, str] = {}
    covered_custom: list[tuple[str, str]] = []
    for logical_id, resource in resources.items():
        rtype = resource.get("Type", "")
        if rtype.startswith("Custom::"):
            limit = _CUSTOM_RESOURCE_TAG_LIMITS.get(rtype)
            if limit is None:
                covered_by = _CUSTOM_RESOURCE_TAG_COVERED_BY.get(rtype)
                if covered_by is not None:
                    covered_custom.append((logical_id, covered_by))
                    continue
                unknown[logical_id] = rtype
                continue
            props = resource.setdefault("Properties", {})
            existing = props.get("ResourceTags") or {}
            if not isinstance(existing, dict):  # pragma: no cover - generator invariant
                unknown[logical_id] = f"{rtype} with a non-map ResourceTags property"
                continue
            merged = {**tags, **existing}
            if len(merged) > limit:
                raise CfnExportUnsupportedError(
                    f"{logical_id} ({rtype}) would receive {len(merged)} tags, but the "
                    f"resource it manages accepts at most {limit}. Remove some resource "
                    "tags and export again; none were silently dropped."
                )
            props["ResourceTags"] = merged
            continue
        if rtype in _UNTAGGABLE:
            continue
        spec = _TAG_PROPERTY.get(rtype)
        if spec is None:
            unknown[logical_id] = rtype
            continue
        prop, shape = spec
        props = resource.setdefault("Properties", {})
        if shape == "map":
            existing = props.get(prop) or {}
            if not isinstance(existing, dict):  # pragma: no cover - defensive
                continue
            # dict(tags) first so an existing entry wins on conflict.
            merged = {**tags, **existing}
            if len(merged) > 50:
                raise CfnExportUnsupportedError(
                    f"{logical_id} ({rtype}) would receive {len(merged)} tags after "
                    "combining the resource's built-in tags with the requested governance "
                    "tags, but AWS accepts at most 50. Remove some resource tags and export "
                    "again; none were silently dropped."
                )
            props[prop] = merged
        else:
            existing_list = props.get(prop) or []
            if not isinstance(existing_list, list):  # pragma: no cover - defensive
                continue
            taken = {t.get("Key") for t in existing_list if isinstance(t, dict)}
            merged = existing_list + [{"Key": k, "Value": v} for k, v in tags.items() if k not in taken]
            if len(merged) > 50:
                raise CfnExportUnsupportedError(
                    f"{logical_id} ({rtype}) would receive {len(merged)} tags after "
                    "combining the resource's built-in tags with the requested governance "
                    "tags, but AWS accepts at most 50. Remove some resource tags and export "
                    "again; none were silently dropped."
                )
            props[prop] = merged

    for logical_id, covered_by in covered_custom:
        owners = [
            resource
            for resource in resources.values()
            if isinstance(resource, dict) and resource.get("Type") == covered_by
        ]
        if not owners:
            unknown[logical_id] = (
                f"{resources[logical_id].get('Type')} claims tag coverage from "
                f"{covered_by}, but this template contains no such owning resource"
            )
            continue

        owner_spec = _TAG_PROPERTY.get(covered_by)
        if owner_spec is None:
            unknown[logical_id] = (
                f"{resources[logical_id].get('Type')} claims tag coverage from "
                f"{covered_by}, but that owner has no classified tag property"
            )
            continue
        owner_property, owner_shape = owner_spec
        owner_tag_keys: set[str] = set()
        for owner in owners:
            value = owner.get("Properties", {}).get(owner_property)
            if owner_shape == "map" and isinstance(value, dict):
                owner_tag_keys.update(str(key) for key in value)
            elif owner_shape == "list" and isinstance(value, list):
                owner_tag_keys.update(
                    str(item.get("Key")) for item in value if isinstance(item, dict) and item.get("Key") is not None
                )
        missing_owner_keys = sorted(set(tags) - owner_tag_keys)
        if missing_owner_keys:
            unknown[logical_id] = (
                f"{resources[logical_id].get('Type')} claims tag coverage from "
                f"{covered_by}, but its owner is missing requested tag keys "
                f"{missing_owner_keys}"
            )

    if unknown:
        # Fail closed, but only when tags were actually requested. A resource type added
        # to the generator later would otherwise silently come out untagged, which is the
        # exact defect this function exists to fix -- one release later and invisible.
        raise CfnExportUnsupportedError(
            "This export cannot apply your resource tags to "
            + ", ".join(f"{lid} ({rtype})" for lid, rtype in sorted(unknown.items()))
            + ". Rather than emit a stack that is only partly tagged, the export is "
            "refused. Deploy through the platform, which tags every resource it creates."
        )


# ---------------------------------------------------------------------------
# Data-bearing resource protection
# ---------------------------------------------------------------------------

# ARCC guidance "Protect storage resources from accidental deletion or
# replacement" (cnt_h02wszR9St529D) requires BOTH DeletionPolicy and
# UpdateReplacePolicy on every storage-capacity resource, because a replacing
# update is just as destructive as a delete and only DeletionPolicy is widely
# remembered. Its exit criterion is exactly that: "Define DeletionPolicy and
# UpdateReplacePolicy for storage resources in your CloudFormation template."
#
# Keyed on resource TYPE, not logical id, on purpose. A name-keyed list silently
# stops protecting a resource the day somebody renames it or adds a second one —
# and this template already has two Cognito user pools (the gateway pool and the
# MCP-server pool) for exactly that reason. Adding a new data-bearing type is the
# only change that needs a human here.
# Governance over data that lives outside the stack: Custom::RuntimeLogGroup pre-creates and
# governs the runtime's own CloudWatch log groups. It has no physical object of its own, so
# it carries the SAME retention pair as the data it governs -- RetainExceptOnCreate/Retain
# under Retain (CloudFormation sends its Delete only when the operation that created the
# runtime rolls back; a retained stack's deletion skips it and the logs outlive the stack),
# Delete/Delete under Delete -- and is the one non-data type _apply_data_retention stamps.
RETENTION_GOVERNANCE_RESOURCE_TYPES = frozenset({"Custom::RuntimeLogGroup"})

DATA_BEARING_RESOURCE_TYPES = frozenset(
    {
        "AWS::Cognito::UserPool",  # user identities
        "AWS::Bedrock::KnowledgeBase",  # vector index + ingested documents
        "AWS::Bedrock::DataSource",  # ingestion state for the above
        "AWS::BedrockAgentCore::Memory",  # conversation history
        "AWS::S3Vectors::VectorBucket",  # the embeddings themselves
        "AWS::S3Vectors::Index",  # every property is createOnly: an update REPLACES it
        # Logs are data. They are the only record of what the agent was asked and
        # what it answered, so a stack delete should not silently be what destroys
        # an audit trail — but a demo stack should still be able to opt out, which
        # is exactly what the retention policy is for. Stamped here rather than
        # hardcoded Retain in _apply_lambda_log_groups so there is one knob, not two.
        "AWS::Logs::LogGroup",
    }
)


# Resources that hold no data themselves, but without which a RETAINED data resource
# cannot be deleted afterwards. Retaining data and then destroying the only means of
# disposing of it is not protection; it is a resource the operator can never remove.
#
# Proven live in us-east-1, then re-proven with a control against real ingested
# vectors (stacks rtn0919-retain, kbretain-0919150116, kbctl-0919150613).
#
# The purge runs when the DATA SOURCE is deleted, using this role — measured, not
# assumed: list-vectors went 1 -> 0 on delete-data-source, before the knowledge base
# was touched. AWS::Bedrock::KnowledgeBase re-attempts the same purge on its own
# delete, naming the same data source id in failureReasons, so both deletes fail if
# the role is gone. Worth keeping straight, because an operator reading only "the
# knowledge base purges its vectors" debugs the wrong API call.
#
# With the role retained: data source and knowledge base both delete first time.
# With the role deleted first and the vector store fully intact — the pre-fix
# situation, in the textbook order — delete-data-source returns DELETE_UNSUCCESSFUL,
# "Unable to delete data from vector store", the vector count stays at 1, and the
# knowledge base then fails the same way. Recreating ONLY the role, touching nothing
# else, makes the identical delete succeed and the count go to 0. So the role is the
# whole cause and deletion ordering is not a mitigation. The role's inline Policies
# block travels with it byte-identical across the stack delete (same policy sha256
# before and after) and is sufficient on its own.
#
# Keyed by the data resource's TYPE, for the same reason DATA_BEARING_RESOURCE_TYPES
# is: a logical-id list stops protecting anything the day somebody renames a resource.
# The generalisable question when adding a type here is "what does this resource need
# in order to delete ITSELF, and is that retained too?"
DELETION_DEPENDENCIES: dict[str, tuple[str, ...]] = {
    "AWS::Bedrock::KnowledgeBase": ("KnowledgeBaseRole",),
}


def _apply_deletion_dependencies(template: dict, policy: str) -> list[str]:
    """Retain whatever a retained data resource needs in order to be deletable.

    Only meaningful for ``Retain``: under ``Delete`` the data resource goes with the
    stack, so nothing has to outlive it, and leaving an IAM role behind would be a
    gratuitous orphan.

    The alternative — which this replaces — was to tell the operator in teardown.sh
    to recreate the role by hand. That is worse on two counts. It is a multi-step
    recipe run against a stack that no longer exists, and the trust-and-permissions
    policy an operator can be told to paste in a shell one-liner is far broader than
    the one the template had (``s3vectors:*`` on ``*``), so the documented workaround
    ended by advising exactly the unconditioned wildcard ARCC cnt_SFJJhkOueCPRkd
    warns against. Retaining the real, already-scoped role avoids both.
    """
    if policy != "Retain":
        return []

    present = {resource.get("Type") for resource in template.get("Resources", {}).values()}
    touched = []
    for data_type, dependency_ids in DELETION_DEPENDENCIES.items():
        if data_type not in present:
            continue
        for logical_id in dependency_ids:
            resource = template.get("Resources", {}).get(logical_id)
            if resource is None:
                # Not a silent skip: the mapping naming a resource this template does
                # not have means the two have drifted, and the consequence is an
                # un-deletable retained resource in the customer's account.
                logger.warning(
                    "DELETION_DEPENDENCIES names %s for %s, but this template has no such "
                    "resource: a retained %s may not be deletable",
                    logical_id,
                    data_type,
                    data_type,
                )
                continue
            # RetainExceptOnCreate, like the data it exists for: retained on delete and
            # replacement, but cleaned up if the stack's FIRST create rolls back.
            resource["DeletionPolicy"] = "RetainExceptOnCreate"
            resource["UpdateReplacePolicy"] = "Retain"
            touched.append(logical_id)
    return sorted(touched)


def _apply_data_retention(template: dict, policy: str) -> list[str]:
    """Stamp *policy* onto every data-bearing resource. Returns the ids touched.

    The returned list is not decoration: the generated README enumerates it, and
    the test suite asserts it is non-empty for every component combination that
    creates data. A silent empty return is the failure mode to catch.
    """
    if policy not in ("Retain", "Delete"):
        raise ValueError(f"data retention policy must be Retain or Delete, got {policy!r}")

    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") in DATA_BEARING_RESOURCE_TYPES:
            # The knob stays Retain/Delete; the stamped VALUE for Retain is
            # RetainExceptOnCreate. Plain Retain also applies to the rollback of a
            # FAILED FIRST CREATE, so an initial deploy that dies part-way (a quota,
            # a bad parameter) leaves empty pools/log groups/stores behind that then
            # collide with every retry by name. RetainExceptOnCreate deletes what the
            # failing initial operation created and still retains on every later
            # stack delete or replacing update -- the protection Retain is for.
            resource["DeletionPolicy"] = "RetainExceptOnCreate" if policy == "Retain" else "Delete"
            resource["UpdateReplacePolicy"] = policy
            touched.append(logical_id)
        if resource.get("Type") in RETENTION_GOVERNANCE_RESOURCE_TYPES:
            # See RETENTION_GOVERNANCE_RESOURCE_TYPES. Not appended to `touched`: it is
            # governance over the runtime's groups, not a data store of its own, so the
            # README's list of retained stores and the teardown notice stay accurate.
            resource["DeletionPolicy"] = "RetainExceptOnCreate" if policy == "Retain" else "Delete"
            resource["UpdateReplacePolicy"] = "Retain" if policy == "Retain" else "Delete"
        if resource.get("Type") == "AWS::Cognito::UserPool":
            # Cognito's own guard must stay INACTIVE under BOTH values. DeleteUserPool
            # against DeletionProtection=ACTIVE returns InvalidParameterException, so:
            # under Delete an ACTIVE pool would hang its own teardown, and under Retain
            # (RetainExceptOnCreate) an ACTIVE pool would make the rollback of a failed
            # FIRST create fail its delete and leave the stack ROLLBACK_FAILED -- worse
            # than the stranded pool it replaces. Deletion safety for a retained pool
            # therefore comes from the CloudFormation policies plus IAM; an operator who
            # also wants the service-level guard enables it via the Cognito console AFTER
            # the first successful deploy, which the generated README documents (including
            # the drift warning and why the one-field CLI command is unsafe). Stamped from
            # the knob so a future value cannot drift the two apart.
            resource.setdefault("Properties", {})["DeletionProtection"] = "INACTIVE"
    return sorted(touched)


def _split_retained(template: dict, retained: list[str]) -> tuple[list[str], list[str]]:
    """Separate retained log groups from retained data stores. Returns (logs, stores).

    They need different words and carry different consequences, and conflating them
    made the teardown notice wrong in the commonest case. A runtime-only export
    retains exactly one resource — the CFN provider Lambda's log group — and the
    notice told the operator it "holds user identities, ingested documents and/or
    conversation history". None of that is in a Lambda log group, and a warning that
    is wrong once is a warning the operator stops reading, which is the whole reason
    the quiet-when-there-is-nothing-to-lose rule exists.

    The consequence is specific to log groups, too: a retained group makes a
    redeploy under the same stack name fail at
    ``[AWS::EarlyValidation::ResourceExistenceCheck]``, which reports ``"Hooks": []``
    and names no resource. The operator cannot act on that error without being told
    beforehand what to delete, so the notice below hands them the command.
    """
    resources = template.get("Resources", {})
    logs = [r for r in retained if resources.get(r, {}).get("Type") == "AWS::Logs::LogGroup"]
    return logs, [r for r in retained if r not in set(logs)]


# ---------------------------------------------------------------------------
# Role governance: permissions boundary and optional role naming
# ---------------------------------------------------------------------------

PERMISSIONS_BOUNDARY_CONDITION = "HasPermissionsBoundary"
EXPLICIT_ROLE_NAMES_CONDITION = "HasExplicitRoleNames"

# Whether the runtime may invoke any AgentCore peer at all. Off unless the export names
# peers or the recipient passes some, because the permission to invoke another agent is
# not something an export should acquire by default.
A2A_PEERS_CONDITION = "HasA2APeerRuntimeArns"

# One AgentCore runtime ARN, optionally qualified by an endpoint. Both shapes are
# resource types of bedrock-agentcore:InvokeAgentRuntime.
#
# Character-for-character the same body as ``_A2A_PEER_ARN_RE`` in the generated agent, and
# that matters more than it looks: `[0-9]` rather than `\d` because `\d` matches Arabic-Indic
# digits in Python and ASCII only in the Java engine CloudFormation validates
# ``AllowedPattern`` with, so the shorthand would make the deploy-time check and the runtime
# check disagree on inputs neither author would think to try.
_A2A_PEER_ARN = (
    r"arn:aws[a-z-]*:bedrock-agentcore:[a-z0-9-]+:[0-9]{12}:runtime/[A-Za-z0-9_-]+"
    r"(/runtime-endpoint/[A-Za-z0-9_-]+)?"
)

# A comma-separated list of them, or empty. Shaped, not merely non-empty, because the value
# goes straight into an IAM policy's Resource, and the two things that buys are different
# sizes. The small one: a typo CloudFormation would otherwise accept fails at role creation
# instead, and the rollback names the bad value and the role's logical id but NOT the
# parameter that supplied it — measured, with `Resource: ["\n"]` hardcoded into a mirror role:
# `Resource ... must be in ARN format or "*"`, IAM `InvalidRequest`. So the recipient is told
# what is malformed and left to find where it came from. The large one: a deliberately loose
# entry — a trailing `*`, say — is how "one named peer" quietly becomes every agent in the
# account, and no later layer catches that at all, because it is a perfectly valid policy.
#
# The whole pattern is optional rather than an `^$|...` alternation so it means the same thing
# under CloudFormation's full-match semantics as it does to `re.fullmatch` in our own tests.
# ConstraintDescription is not decoration either: measured both ways on the real template, a
# failed value quotes the ConstraintDescription when one is set and the raw regex when it is
# not. Neither form names the offending peer, so the description has to.
A2A_PEER_ARNS_PATTERN = rf"^({_A2A_PEER_ARN}(,{_A2A_PEER_ARN})*)?$"


# Confused-deputy protection for the service-principal trust policies.
#
# A role trust policy is a resource policy. When it names only a service — as every
# role here did — the service will assume the role for *any* caller it acts for,
# including one in another AWS account who persuades the same service to reach into
# this one. ARCC cnt_vBC0kXE8PNHqrW requires service-to-service access to be
# constrained with the aws:SourceAccount / aws:SourceArn condition keys, which the
# calling service populates from x-amz-source-account / x-amz-source-arn.
#
# The condition can only be added where the service is known to send those headers:
# a service that does not will simply fail to assume the role, and the failure
# surfaces as an unrelated-looking resource error at deploy time. So this map is an
# allowlist of the principals confirmed to send them, not every principal we emit.
#
#   bedrock.amazonaws.com          — AWS documents exactly this trust policy for a
#                                    Knowledge Base service role, both keys.
#   bedrock-agentcore.amazonaws.com — verified live on two independent paths, each
#                                    with a wrong-value negative control, which is
#                                    what makes the pass meaningful: an absent
#                                    context key makes StringEquals and ArnLike
#                                    evaluate false, so if AgentCore did not send
#                                    the headers the correct-account arm would have
#                                    failed too. Gateway: stack CREATE_COMPLETE and
#                                    a real MCP tools/call returned the Lambda's own
#                                    output; a deliberately wrong account and a
#                                    deliberately wrong ARN both rolled back.
#                                    Memory: CreateMemory reached ACTIVE, and both
#                                    wrong values were rejected with "Please provide
#                                    a role with a valid trust policy".
#   lambda.amazonaws.com           — not applicable. Lambda assumes the execution
#                                    role for a function in this account only, and
#                                    AWS does not document these keys for it.
#
# Do NOT narrow the resource portion of aws:SourceArn below. The source ARN is the
# ARN of the *calling AgentCore resource*, so it is gateway/... for a gateway role
# and memory/... for a memory execution role. One shared entry narrowed to
# ``gateway/*`` passes every gateway test and then breaks every memory deploy — that
# was tested, not guessed. Tightening it further means emitting the condition per
# role type rather than per service principal.
#
# One note for whoever debugs a regression here: the AgentCore failure does not
# surface on the role. It surfaces at *target* creation, as
# "Gateway service is not authorized to perform AssumeRole on Gateway role. Update
# trust policy and retry", against the AWS::BedrockAgentCore::GatewayTarget — two
# resources after the cause.
_TRUST_SOURCE_CONDITIONS: dict[str, dict] = {
    "bedrock.amazonaws.com": {
        "StringEquals": {"aws:SourceAccount": {"Ref": "AWS::AccountId"}},
        "ArnLike": {"aws:SourceArn": {"Fn::Sub": "arn:${AWS::Partition}:bedrock:${AWS::Region}:${AWS::AccountId}:*"}},
    },
    "bedrock-agentcore.amazonaws.com": {
        "StringEquals": {"aws:SourceAccount": {"Ref": "AWS::AccountId"}},
        "ArnLike": {
            "aws:SourceArn": {"Fn::Sub": "arn:${AWS::Partition}:bedrock-agentcore:${AWS::Region}:${AWS::AccountId}:*"}
        },
    },
}


def _apply_trust_source_conditions(statement: dict) -> bool:
    """Constrain one trust statement to this account, if its principal supports it.

    Returns whether a condition was added, so the caller can report the count and a
    test can assert the pass is not silently doing nothing.
    """
    service = statement.get("Principal", {}).get("Service")
    condition = _TRUST_SOURCE_CONDITIONS.get(service)
    if not condition:
        return False
    # Merge rather than assign: a caller-supplied condition on the same statement
    # would otherwise be dropped, which would loosen the policy while appearing to
    # tighten it.
    existing = statement.setdefault("Condition", {})
    for operator, keys in condition.items():
        existing.setdefault(operator, {}).update(keys)
    return True


def _apply_role_governance(template: dict) -> list[str]:
    """Make every emitted role boundary-aware and its name optional.

    Two things a regulated account routinely mandates and this template gave it
    no way to express.

    A permissions boundary is the control that lets a security team allow a
    workload to create its own roles at all: it caps what those roles can ever be
    granted, no matter what the stack asks for. Without a boundary parameter the
    recipient's only options were to hand the deploying principal unbounded
    iam:CreateRole or not deploy.

    Explicit ``RoleName`` values were the other blocker. Eight roles set one, so
    the stack always required ``CAPABILITY_NAMED_IAM`` — which many accounts deny
    outright — and the fixed ``AgentCore*-`` prefix collides with accounts whose
    SCPs or naming conventions mandate their own. Named roles stay the default
    because they are far easier to find in an audit, but setting
    ``UseExplicitRoleNames=false`` lets CloudFormation generate the names and the
    stack then deploys under plain ``CAPABILITY_IAM``.

    Both are applied in one pass over the finished Resources block for the same
    reason as ``_apply_data_retention``: a future branch that adds a role cannot
    forget to opt in. Returns the role ids touched.
    """
    template.setdefault("Conditions", {}).update(
        {
            PERMISSIONS_BOUNDARY_CONDITION: {"Fn::Not": [{"Fn::Equals": [{"Ref": "PermissionsBoundaryArn"}, ""]}]},
            EXPLICIT_ROLE_NAMES_CONDITION: {"Fn::Equals": [{"Ref": "UseExplicitRoleNames"}, "true"]},
        }
    )
    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::IAM::Role":
            continue
        properties = resource.setdefault("Properties", {})
        properties["PermissionsBoundary"] = {
            "Fn::If": [PERMISSIONS_BOUNDARY_CONDITION, {"Ref": "PermissionsBoundaryArn"}, {"Ref": "AWS::NoValue"}]
        }
        if "RoleName" in properties:
            properties["RoleName"] = {
                "Fn::If": [EXPLICIT_ROLE_NAMES_CONDITION, properties["RoleName"], {"Ref": "AWS::NoValue"}]
            }
        for statement in properties.get("AssumeRolePolicyDocument", {}).get("Statement", []):
            _apply_trust_source_conditions(statement)
        touched.append(logical_id)
    return sorted(touched)


# ---------------------------------------------------------------------------
# Customer-managed encryption keys
# ---------------------------------------------------------------------------

CUSTOMER_KEY_CONDITION = "HasCustomerManagedKey"


# A factory, not a shared constant, and the difference is not cosmetic. One dict
# object referenced from several places in the template makes yaml.dump emit a YAML
# anchor and aliases (&id001 / *id001) instead of repeating the mapping, and
# CloudFormation refuses the whole template with "Template error: YAML aliases are
# not allowed in CloudFormation templates" — before it creates a single resource.
# The template still round-trips through yaml.safe_load perfectly and looks correct
# to a reader, so nothing but a real deploy or an explicit assertion catches it.
# Proven live: a bundle whose deploy.sh had already built the dependency bundle,
# created the bucket and uploaded all three artifacts failed at CreateChangeSet with
# exactly that error. _dump_template's NoAliasDumper is the second half of the fix;
# this half stops the aliases existing, that half makes them unrepresentable.
def _customer_key_ref() -> dict:
    return {"Ref": "CustomerManagedKeyArn"}


# Resource type -> (property name, property value when a key is supplied).
#
# Every entry was read off the live CloudFormation registry
# (``aws cloudformation describe-type --type RESOURCE --type-name <type>``), not
# off documentation, because the property names are not consistent even within one
# service: AgentCore Memory and PolicyEngine say EncryptionKeyArn, AgentCore
# Gateway says KmsKeyArn, S3 Vectors says EncryptionConfiguration.KmsKeyArn and
# needs SseType flipped to aws:kms alongside it, and Bedrock DataSource nests it
# one level down again.
#
# Three types in this template deliberately have NO entry, and their absence is a
# finding rather than an omission:
#   AWS::Bedrock::KnowledgeBase   - no encryption property exists. The KB's vector
#                                   data is encrypted by the S3 Vectors bucket and
#                                   index below, and its ingestion state by the
#                                   data source; there is nothing left on the KB.
#   AWS::BedrockAgentCore::Runtime - no encryption property exists.
#   AWS::Cognito::UserPool         - no encryption property exists; Cognito does
#                                   not support a customer-managed key at rest.
# So a customer-managed key covers conversation memory, embeddings and ingestion
# state. It does not cover the user directory. The generated README says so.
# The second element is a *factory* for the same reason ``_customer_key_ref`` is one:
# a value shared between two resources becomes a YAML alias and the template is then
# rejected outright.
CUSTOMER_KEY_PROPERTIES: dict[str, tuple[str, Callable[[], object]]] = {
    "AWS::BedrockAgentCore::Memory": ("EncryptionKeyArn", _customer_key_ref),
    "AWS::BedrockAgentCore::Gateway": ("KmsKeyArn", _customer_key_ref),
    "AWS::S3Vectors::VectorBucket": (
        "EncryptionConfiguration",
        lambda: {"SseType": "aws:kms", "KmsKeyArn": _customer_key_ref()},
    ),
    "AWS::S3Vectors::Index": (
        "EncryptionConfiguration",
        lambda: {"SseType": "aws:kms", "KmsKeyArn": _customer_key_ref()},
    ),
    "AWS::Bedrock::DataSource": (
        "ServerSideEncryptionConfiguration",
        lambda: {"KmsKeyArn": _customer_key_ref()},
    ),
    # The policy engine stores the Cedar statements themselves — who may invoke
    # which tool. Read off the live registry like the rest; the property is
    # createOnly, so supplying a key to a stack that already has an engine
    # REPLACES the engine. That is survivable here and nowhere else in this table:
    # the statements are rebuilt from the template by Custom::AgentCorePolicy,
    # which already DependsOn the engine, so a replacement re-creates them rather
    # than losing them. It does mean the engine id changes, which is why the
    # gateway's PolicyEngineConfiguration reads it with Fn::GetAtt.
    "AWS::BedrockAgentCore::PolicyEngine": ("EncryptionKeyArn", _customer_key_ref),
    # Lambda's KmsKeyArn encrypts the function's environment variables at rest.
    # Only applied to functions that HAVE environment variables — see
    # _apply_customer_key. Found by Checkov CKV_AWS_173 on the emitted template.
    "AWS::Lambda::Function": ("KmsKeyArn", _customer_key_ref),
    # The log groups. Unlike every other entry, the key is used by the CloudWatch
    # Logs *service* rather than by one of this stack's roles, so no inline policy
    # can authorize it — the key policy has to name the
    # logs.<region>.amazonaws.com service principal, and CreateLogGroup fails
    # outright if it does not. That requirement is why this entry was originally
    # left out; the generated README's key-policy section now carries the statement.
    # Found by Checkov CKV_AWS_158.
    "AWS::Logs::LogGroup": ("KmsKeyId", _customer_key_ref),
    # The AgentCore runtime's OWN log groups — the ones holding the conversation.
    # AWS::BedrockAgentCore::Runtime has no logging or encryption property at all (see
    # the note above), and the service creates these groups outside CloudFormation, so
    # Custom::RuntimeLogGroup is the only thing that can reach them. It passes this ARN
    # to CreateLogGroup/AssociateKmsKey, and the same logs.<region>.amazonaws.com
    # key-policy statement the entry above needs is what makes that work.
    "Custom::RuntimeLogGroup": ("KmsKeyArn", _customer_key_ref),
}

# Role logical id -> the encrypted resource types that role has to be able to use
# the key for. A static "grant every role kms:Decrypt" list would undo the
# least-privilege work in _apply_role_governance's neighbours: the runtime role
# exists in every combination, so it would carry key access even in a stack with
# nothing encrypted. Keyed this way, a role only gets the grant when a resource it
# actually touches is in the template.
CUSTOMER_KEY_ROLE_DEPENDENCIES: dict[str, frozenset[str]] = {
    "RuntimeExecutionRole": frozenset({"AWS::BedrockAgentCore::Memory", "AWS::BedrockAgentCore::Gateway"}),
    "MemoryExecutionRole": frozenset({"AWS::BedrockAgentCore::Memory"}),
    "GatewayRole": frozenset({"AWS::BedrockAgentCore::Gateway"}),
    "KnowledgeBaseRole": frozenset(
        {"AWS::S3Vectors::VectorBucket", "AWS::S3Vectors::Index", "AWS::Bedrock::DataSource"}
    ),
    # The custom-resource Lambda writes the Cedar statements into the engine, so an
    # encrypted engine makes it a key user. Stated explicitly rather than left to
    # the Lambda-environment inference below, because the grant is needed for a
    # different reason: AgentCore's policy APIs run a forward-access-session KMS
    # check against the caller, and a role without kms:Decrypt on the engine's key
    # gets an AccessDenied from the *policy* call, not a decrypt error.
    # Custom::RuntimeLogGroup for the same class of reason: the Lambda hands the key
    # ARN to CreateLogGroup/AssociateKmsKey, and CloudWatch Logs validates the key as
    # the caller before accepting it. A role holding logs:AssociateKmsKey but nothing
    # on the key gets an AccessDenied from the LOGS call, which reads as a log-group
    # permission problem and is not one. This entry is why the whole feature works
    # from a least-privilege role rather than only from an administrator's.
    "CfnProviderRole": frozenset({"AWS::BedrockAgentCore::PolicyEngine", "Custom::RuntimeLogGroup"}),
}

CUSTOMER_KEY_POLICY_NAME = "CustomerManagedKeyAccess"


def _customer_key_policy() -> dict:
    """The inline policy a role needs to use the supplied key.

    ``Resource`` is the single supplied key ARN — the whole point of the feature is
    that the customer can revoke it, so a wildcard here would be self-defeating.

    ``kms:CreateGrant`` is here because the AWS services holding this data create
    grants on the caller's behalf rather than calling Decrypt directly. Per ARCC
    cnt_SFJJhkOueCPRkd it carries the ``kms:GrantIsForAWSResource`` condition, which
    is what stops the grant being usable to hand the key to an arbitrary principal:
    KMS only honours the call when the grantee is an AWS service acting for this
    request.
    """
    return {
        "PolicyName": CUSTOMER_KEY_POLICY_NAME,
        "PolicyDocument": {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "UseCustomerManagedKey",
                    "Effect": "Allow",
                    "Action": [
                        "kms:Decrypt",
                        "kms:GenerateDataKey",
                        # The envelope-encryption variant, and the one that is easy
                        # to leave out: a service that only ever needs the wrapped
                        # data key never calls GenerateDataKey. Its absence showed up
                        # live as "missing required kms:GenerateDataKeyWithoutPlaintext
                        # permission" — and only for a least-privilege caller, so an
                        # AdministratorAccess deploy proves nothing about it.
                        "kms:GenerateDataKeyWithoutPlaintext",
                        "kms:DescribeKey",
                    ],
                    "Resource": _customer_key_ref(),
                },
                {
                    "Sid": "GrantCustomerManagedKeyToAwsResources",
                    "Effect": "Allow",
                    "Action": "kms:CreateGrant",
                    "Resource": _customer_key_ref(),
                    "Condition": {"Bool": {"kms:GrantIsForAWSResource": "true"}},
                },
            ],
        },
    }


def _apply_customer_key(template: dict) -> tuple[list[str], list[str]]:
    """Wire the optional customer-managed key through the finished template.

    Returns ``(encrypted resource ids, roles granted key access)``. Both are used
    by the generated README and pinned by the contract tests, so a branch that adds
    an encryptable resource and forgets it shows up as an empty list rather than as
    silently unencrypted data.

    Applied in one pass at the end for the same reason as ``_apply_data_retention``
    and ``_apply_role_governance``: keying on resource type means a future
    ``_add_*`` call cannot forget to opt in.
    """
    template.setdefault("Conditions", {})[CUSTOMER_KEY_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [_customer_key_ref(), ""]}]
    }

    resources = template.get("Resources", {})
    encrypted: list[str] = []
    present_types: set[str] = set()
    # Roles derived from the template rather than declared: a Lambda whose
    # environment is encrypted with a customer key cannot start unless its own
    # execution role holds kms:Decrypt on that key, and the role is right there in
    # the function's Role property. Reading it beats maintaining a second list that
    # can fall out of step with which functions exist.
    lambda_roles: set[str] = set()

    for logical_id, resource in resources.items():
        resource_type = resource.get("Type", "")
        mapping = CUSTOMER_KEY_PROPERTIES.get(resource_type)
        if mapping is None:
            continue
        properties = resource.setdefault("Properties", {})

        if resource_type == "AWS::Lambda::Function":
            if "Environment" not in properties:
                # Nothing of ours to encrypt. On a function with no environment
                # variables KmsKeyArn covers only SnapStart snapshots, which this
                # template does not use, so setting it would buy nothing and cost
                # the function's role a kms:Decrypt grant. Checkov's CKV_AWS_173
                # scopes itself the same way.
                continue
            role = properties.get("Role")
            get_att = role.get("Fn::GetAtt") if isinstance(role, dict) else None
            if get_att:
                lambda_roles.add(get_att[0])

        name, build_value = mapping
        properties[name] = {"Fn::If": [CUSTOMER_KEY_CONDITION, build_value(), {"Ref": "AWS::NoValue"}]}
        encrypted.append(logical_id)
        present_types.add(resource_type)

    needs_key = set(lambda_roles)
    for role_id, needed_types in CUSTOMER_KEY_ROLE_DEPENDENCIES.items():
        if needed_types & present_types:
            needs_key.add(role_id)

    granted: list[str] = []
    for role_id in sorted(needs_key):
        role = resources.get(role_id)
        if role is None or role.get("Type") != "AWS::IAM::Role":
            continue
        policies = role.setdefault("Properties", {}).setdefault("Policies", [])
        # Fn::If on the list entry, not on the whole Policies list: the other
        # inline policies must survive when no key is supplied.
        policies.append({"Fn::If": [CUSTOMER_KEY_CONDITION, _customer_key_policy(), {"Ref": "AWS::NoValue"}]})
        granted.append(role_id)

    return sorted(encrypted), sorted(granted)


# ---------------------------------------------------------------------------
# Resource scoping for the emitted policies
# ---------------------------------------------------------------------------
#
# ARCC cnt_AGx9pUNpmdOVZB: specific actions on specific resources, not "*". The
# actions were already exact everywhere; the resources were "*" in eighteen
# statements. These helpers exist so that four roles that all invoke Bedrock
# cannot drift into four different answers about what a model ARN looks like, and
# so each remaining "*" is a deliberate, commented decision rather than a default.


def _bedrock_model_resources() -> list[dict]:
    """The ARN families ``bedrock:InvokeModel`` actually needs.

    Deliberately not the exported ``ModelId``: the parameter is overridable, and a
    policy pinned to the export-time value denies an operator who legitimately
    changes it — a failure that surfaces as a runtime AccessDenied, not a deploy
    error. The families below are the narrowing that survives that override.

    The region is wildcarded on the foundation-model family because that is what
    cross-region inference requires: invoking a ``us.`` inference profile calls the
    model in whichever region the profile routes to, and denying the other regions
    breaks the default configuration. Profiles stay account-scoped.
    """
    return [
        {"Fn::Sub": "arn:${AWS::Partition}:bedrock:*::foundation-model/*"},
        {"Fn::Sub": "arn:${AWS::Partition}:bedrock:*:${AWS::AccountId}:inference-profile/*"},
        {"Fn::Sub": "arn:${AWS::Partition}:bedrock:*:${AWS::AccountId}:application-inference-profile/*"},
    ]


def _bedrock_model_arn(model_id: str) -> dict:
    """The ARN that names *model_id* to Bedrock — profile or foundation model.

    A geography-prefixed id (``us.anthropic.claude-sonnet-5``) is a cross-region
    inference profile, not a foundation model, and profiles are account-qualified.
    Putting one under a ``foundation-model/`` path is accepted by CloudFormation and
    fails only when the Lambda runs, which is how it survived: proven live,
    ``RetrieveAndGenerate`` returned

        ValidationException ... Received validation exception when calling
        GetInferenceProfile for
        arn:aws:bedrock:us-east-1::foundation-model/us.anthropic.claude-sonnet-5

    on a stack that reached CREATE_COMPLETE with ``FunctionError: null`` — the error
    was in the response body, so even an invoke-based smoke test reads as a pass.
    Bedrock resolves the ``us.`` prefix as a profile and then cannot find one at that
    ARN. IAM was already correct here (``_bedrock_model_resources`` grants both
    families), so an IAM review passes it straight through.

    A plain on-demand id keeps the unqualified ``foundation-model/`` form, which is
    the correct shape for it; embedding models in particular have no profiles at all.
    ``${AWS::Partition}`` rather than a literal ``aws`` so the template is not
    silently wrong in GovCloud or China.
    """
    if is_inference_profile_id(model_id):
        return {
            "Fn::Sub": f"arn:${{AWS::Partition}}:bedrock:${{AWS::Region}}:${{AWS::AccountId}}"
            f":inference-profile/{model_id}"
        }
    return {"Fn::Sub": f"arn:${{AWS::Partition}}:bedrock:${{AWS::Region}}::foundation-model/{model_id}"}


def _log_group_resources() -> list[dict]:
    """Log groups in this account and region.

    One pattern, not two. ``PutLogEvents`` is authorized against the
    ``log-group:<name>:log-stream:<name>`` ARN while ``CreateLogGroup`` is
    authorized against ``log-group:<name>``, which looks like it needs both shapes
    listed — but an IAM ``*`` matches any character including ``:`` and ``/``, so
    the trailing wildcard already covers the stream ARN. IAM Access Analyzer
    reports the second entry as REDUNDANT_RESOURCE, which is how this was settled.

    The group name stays wildcarded because AgentCore derives it from the runtime
    id it mints at create time.
    """
    return [{"Fn::Sub": "arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:*"}]


# Where AgentCore puts a runtime's own logs: one group per endpoint, named
# ``<prefix>/<runtimeId>-<qualifier>``. Verified live rather than read off the docs,
# and the finding that matters is the plural: a runtime with a named endpoint has BOTH
# ``-DEFAULT`` and ``-<endpointName>``, both created at stack-create time before any
# invoke, and the invoked qualifier is the one that receives the conversation.
RUNTIME_LOG_GROUP_PREFIX = "/aws/bedrock-agentcore/runtimes"


def _runtime_log_group_resources() -> list[dict]:
    """Only the AgentCore runtime log groups, for the governance custom resource.

    Deliberately narrower than ``_log_group_resources``: that one authorizes writing
    to any group in the account because AgentCore mints the name, while this
    authorizes *changing settings on* groups — including DisassociateKmsKey, which on
    the wrong group would make an unrelated team's existing log data unreadable. The
    runtime prefix is fixed by the service, so there is no reason for this to be wide.
    """
    return [
        {
            "Fn::Sub": (
                "arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:"
                f"log-group:{RUNTIME_LOG_GROUP_PREFIX}/*"
            )
        }
    ]


# ---------------------------------------------------------------------------
# The AgentCore IAM prefix
# ---------------------------------------------------------------------------
#
# Every AgentCore action this template grants is prefixed ``bedrock-agentcore:``.
# There is no ``bedrock-agentcore-control:`` IAM prefix, and no
# ``agent-credential-provider:`` service at all. Both mistakes were in this file.
#
# The confusion is understandable: ``bedrock-agentcore`` and
# ``bedrock-agentcore-control`` are both real API endpoints and both have their own
# botocore client, so ``bedrock-agentcore-control:GetMemory`` reads like the
# control-plane counterpart of a data-plane call. But an IAM service prefix is the
# SigV4 *signing name*, not the endpoint prefix, and both of those clients report
# ``signingName: bedrock-agentcore``. One namespace covers both planes.
#
# This is a silent failure, which is why it survived. IAM accepts a policy naming a
# service that does not exist -- no validation error at PutRolePolicy, no error at
# stack create, and the stack goes CREATE_COMPLETE. The statement simply authorizes
# nothing, so the first denial appears at runtime, in a different place, as an
# AccessDeniedException on a call whose permission is visibly "granted" in the
# console. Two statements here were void in their entirety (evaluation access, and
# credential-provider access) and several others were half-void.
#
# Checked with two oracles rather than by reading documentation, because the two
# answer different questions:
#   * botocore's service models settle the PREFIX. `signingName` is the prefix, and
#     a service that is not in botocore at all (``agent-credential-provider``)
#     raises UnknownServiceError.
#   * IAM Access Analyzer (``validate-policy``) settles individual ACTIONS. IAM
#     actions do not map 1:1 to API operations -- AuthorizeAction,
#     PartiallyAuthorizeActions and InvokeGateway are all real IAM actions with no
#     SDK operation behind them, so "absent from botocore" does not mean invalid.
# An action was only changed where both oracles agreed. INVALID_SERVICE_IN_ACTION
# from Access Analyzer is the finding that catches the prefix error; add a new
# AgentCore grant and it is worth re-running.
def _agentcore_resources(*paths: str) -> list[dict]:
    """AgentCore resources of the given ``kind/*`` shapes in this account/region.

    The id stays wildcarded rather than being pinned with ``Fn::GetAtt`` for two
    reasons. The gateway role and the memory execution role are passed to the very
    resources they would have to name, so naming them is a circular dependency.
    And the AgentCore resource types publish no ``Arn`` attribute that this
    generator has verified — cfn-lint ships no schema for them either, so a wrong
    ``GetAtt`` would not fail the lint gate, it would fail the deploy.

    Account and region scoping is what is left, and it is not nothing: it stops a
    compromised runtime from reaching another region's or another account's
    gateway or memory, which "*" permitted outright.
    """
    return [
        {"Fn::Sub": f"arn:${{AWS::Partition}}:bedrock-agentcore:${{AWS::Region}}:${{AWS::AccountId}}:{path}"}
        for path in paths
    ]


def _agentcore_own_resource(logical_id: str, arn_attribute: str) -> list[dict]:
    """This stack's own AgentCore resource, by ARN, and its sub-resources.

    ``kind/*`` — which is what these statements used to say — is account-wide, and
    account-wide is not a theoretical problem here. Two agents exported from this
    platform into one account each get a runtime role that can call ``GetMemory``,
    ``ListActors`` and ``RetrieveMemoryRecords`` on *every* memory in the region,
    including the other agent's. That was proven, not inferred: a replica of one
    agent's runtime role read the other agent's memory and enumerated its end users'
    Cognito subject ids as actor ids. Conversation history and end-user identifiers
    are exactly the data a regulated recipient runs two agents to keep apart.

    ARCC cnt_AGx9pUNpmdOVZB: specific actions on specific resources. The action
    lists were already exact; this makes the resources exact too.

    Both types publish an ARN attribute — ``GatewayArn`` and ``MemoryArn``, verified
    against the CloudFormation resource registry (``describe-type``) rather than
    assumed, because a wrong ``GetAtt`` on these types does not fail cfn-lint: no
    schema ships for them, so it fails the deploy. Using the ARN attribute directly
    also avoids re-deriving the ARN shape from an id, which is the other way this
    goes wrong.

    The second entry covers sub-resources (a gateway's targets, a memory's records).
    An IAM ``*`` spans ``/``, so one trailing wildcard is enough.

    Only roles the resource does NOT depend on can use this. The gateway role and the
    memory execution role are passed to the very resources they would name, so for
    them this is a circular dependency and the answer is prefix scoping — see
    ``_agentcore_named_resources``.
    """
    # Two separate dicts rather than one bound to a name and used twice: a shared
    # object is what makes yaml.dump emit an anchor and an alias, which CloudFormation
    # rejects outright. _NoAliasDumper is the backstop; not creating them is the fix.
    # See _customer_key_ref.
    return [
        {"Fn::GetAtt": [logical_id, arn_attribute]},
        {"Fn::Join": ["", [{"Fn::GetAtt": [logical_id, arn_attribute]}, "/*"]]},
    ]


def _agentcore_named_resources(*patterns: str) -> list[dict]:
    """AgentCore resources whose names this stack chose, for the circular cases.

    The gateway role is passed to the gateway and the memory execution role to the
    memory, so neither can name its own resource's ARN without a dependency cycle.
    What they *can* do is scope to the names this template asks for:
    ``${DeploymentName}-gateway`` and ``${DeploymentName}_memory``, to which the
    service appends ``-<10 chars>``. That is strictly narrower than ``kind/*`` and
    needs no attribute, so it cannot be wrong about a shape.

    It is weaker than ``_agentcore_own_resource``: a second stack deployed with the
    same ``DeploymentName`` would be in scope. It cannot exist — these names have to
    be unique in the account — but say so rather than imply exactness.
    """
    return _agentcore_resources(*patterns)


def _agentcore_secret_resources() -> list[dict]:
    """The Secrets Manager namespaces AgentCore identity actually uses.

    ``CreateOauth2CredentialProvider`` stores its client secret as
    ``bedrock-agentcore-identity!default/oauth2/<name>``; older paths used an
    ``agentcore-`` prefix. Both are listed because a deploy that lands on the other
    one fails at create time, and neither reaches a secret this stack does not own.
    """
    return [
        {"Fn::Sub": "arn:${AWS::Partition}:secretsmanager:${AWS::Region}:${AWS::AccountId}:secret:bedrock-agentcore-*"},
        {"Fn::Sub": "arn:${AWS::Partition}:secretsmanager:${AWS::Region}:${AWS::AccountId}:secret:agentcore-*"},
    ]


LAMBDA_CONCURRENCY_CONDITION = "HasLambdaConcurrencyLimit"


def _apply_lambda_concurrency(template: dict) -> list[str]:
    """Cap this stack's Lambda concurrency when the recipient asks for a cap.

    Separate pass rather than a property on each ``_add_*`` for the same reason as
    its neighbours: a future Lambda cannot be added without the knob.
    """
    template.setdefault("Conditions", {})[LAMBDA_CONCURRENCY_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [{"Ref": "LambdaReservedConcurrency"}, -1]}]
    }
    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::Lambda::Function":
            continue
        resource.setdefault("Properties", {})["ReservedConcurrentExecutions"] = {
            "Fn::If": [
                LAMBDA_CONCURRENCY_CONDITION,
                {"Ref": "LambdaReservedConcurrency"},
                {"Ref": "AWS::NoValue"},
            ]
        }
        touched.append(logical_id)
    return sorted(touched)


COGNITO_DOMAIN_SUFFIX_CONDITION = "HasCognitoDomainSuffix"

# 12 hex characters, so "ac-mcp-" + a 40-char DeploymentName + "-" + this stays
# inside the 63-character limit on a Cognito hosted-UI domain prefix. It is also
# exactly the length of an AWS account id, which is what a recipient upgrading an
# existing stack has to pin here.
_COGNITO_DOMAIN_SUFFIX_PATTERN = "^[a-z0-9]{0,12}$"


def _stack_id_suffix() -> dict:
    """The last field of this stack's UUID: 12 hex characters, unique per stack.

    Replaces ``${AWS::AccountId}``, which the Cognito hosted-UI domain published:
    that domain resolves in public DNS and answers unauthenticated OIDC discovery
    with HTTP 200, so anyone who could guess the deployment name could read the
    account id out of the response. An account id is not a secret, but it is the
    first thing needed to aim anything at an account, and there is no reason to hand
    it out to make a name unique.

    It also fixes a collision the account id caused rather than prevented: two
    stacks with the same ``DeploymentName`` in one account derived the *same* domain,
    and the second one failed mid-create on AWS::Cognito::UserPoolDomain. The stack
    id is unique per stack, which is the uniqueness actually wanted here.

    A factory rather than a constant for the reason ``_customer_key_ref`` is one:
    the gateway pool and the MCP-server pool both use it, and a dict shared between
    two resources is emitted as a YAML alias, which CloudFormation rejects outright.
    """
    stack_uuid = {"Fn::Select": [2, {"Fn::Split": ["/", {"Ref": "AWS::StackId"}]}]}
    return {"Fn::Select": [4, {"Fn::Split": ["-", stack_uuid]}]}


def _cognito_domain(prefix: str) -> dict:
    """A hosted-UI domain prefix for *prefix* (``ac`` or ``ac-mcp``).

    The suffix parameter exists for one case only: a recipient updating a stack that
    was created before this change. ``Domain`` is createOnly, so changing it
    REPLACES the domain and every caller's token endpoint moves with it; pinning the
    old ``${AWS::AccountId}`` value keeps the existing URL working.
    """
    return {
        "Fn::If": [
            COGNITO_DOMAIN_SUFFIX_CONDITION,
            {"Fn::Sub": prefix + "-${DeploymentName}-${CognitoDomainSuffix}"},
            {"Fn::Sub": [prefix + "-${DeploymentName}-${StackSuffix}", {"StackSuffix": _stack_id_suffix()}]},
        ]
    }


def _add_cognito_parameters(template: dict) -> None:
    """Parameters shared by both emitted Cognito pools. Idempotent.

    Called from both ``_add_cognito`` and ``_add_mcp_server_cognito`` because either
    may be the only one present, and the "everything" canvas emits both.
    """
    template["Parameters"].setdefault(
        "CognitoDomainSuffix",
        {
            "Type": "String",
            "Default": "",
            "AllowedPattern": _COGNITO_DOMAIN_SUFFIX_PATTERN,
            "ConstraintDescription": "up to 12 lowercase letters or digits, or empty",
            "Description": (
                "Leave empty. The hosted-UI domain is then suffixed with this stack's own id, "
                "which is unique and publishes nothing about the account. Set this ONLY when "
                "updating a stack created before the suffix changed, to the AWS account id the "
                "old domain used, so the existing token endpoint keeps working."
            ),
        },
    )
    template["Parameters"].setdefault(
        "AccessTokenValidityMinutes",
        {
            "Type": "Number",
            "Default": 60,
            "MinValue": 5,
            "MaxValue": 1440,
            "Description": (
                "Lifetime of the OAuth access tokens these pools issue. 60 is Cognito's own "
                "default and what this stack used implicitly; lower it to shorten the window in "
                "which a leaked token is usable. Callers use the client-credentials grant, so "
                "they simply request another token - there are no refresh tokens to consider."
            ),
        },
    )
    template.setdefault("Conditions", {})[COGNITO_DOMAIN_SUFFIX_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [{"Ref": "CognitoDomainSuffix"}, ""]}]
    }


def _add_policy_parameters(template: dict) -> None:
    """The knob on how strictly AgentCore validates the emitted Cedar policies.

    Idempotent, and added only on the path that emits a policy engine, so a template
    without one does not carry a parameter that controls nothing.

    An earlier version of this docstring explained the lenient default with a race:
    FAIL_ON_ANY_FINDINGS runs a findings analysis that calls the gateway, the gateway
    was created moments earlier, and engine-to-gateway authorization had not converged.
    That explanation was wrong, and the wrong part mattered. ``Insufficient permissions
    to call gateway with ID <id>`` was a missing IAM grant on ``CfnProviderRole``, and it
    failed CreatePolicy under BOTH modes — so the shipped default never avoided it. A
    controlled live experiment settled it: same principal, same statement, gateway READY
    for many minutes, ``bedrock-agentcore:InvokeGateway`` on that one gateway ARN as the
    only variable. Without it, CREATE_FAILED in both modes; with it, ACTIVE in both. The
    grant is now part of AgentCorePolicyGatewayResolution, so a policy naming real tools
    can be created at all — which, before, it could not.

    Why the default is still the *lenient* value, which is the opposite of what a
    security review expects. Not a race: FAIL_ON_ANY_FINDINGS makes any finding fail the
    stack, including a finding about a statement the RECIPIENT supplied, and rolling back
    a whole deployment over an advisory finding on someone's own Cedar is not a default
    worth shipping. Measured live, a permit-all is also rejected under strict mode
    *asynchronously*: the call returns 200/CREATING and only the status poll in the
    custom resource catches it. What keeps the policy safe either way is that it names
    each tool explicitly and AgentCore is default-deny, plus two rejections
    IGNORE_ALL_FINDINGS does *not* skip: a wildcard resource, and a gateway that does not
    exist. Strict mode is a supported choice now rather than a trap, and that claim was
    earned rather than reasoned: a generated gateway+policy export was deployed twice
    from this bundle, once per mode, and the generated default permit reached ACTIVE with
    no statusReasons both times. So a recipient who wants findings to gate the deploy can
    set it.

    What the grant costs is real and is not hidden: for the life of the deploy, the
    custom-resource Lambda can invoke the tools this stack's gateway fronts. It is
    scoped to that gateway's ARN and its targets, never account-wide, and README >
    Authorization says so outright. The alternative was shipping a policy resource that
    cannot reach ACTIVE, which is not a security posture — it is a broken feature that
    leaves the gateway's authorization to whatever default-deny does on its own.

    Only the strictness-increasing direction is offered. ``enforcementMode`` is
    deliberately NOT a parameter: its other value, LOG_ONLY, *records* a denial instead
    of enforcing it, so an engine whose policies are all LOG_ONLY permits everything
    while looking exactly like one that does not. This template's entire authorization
    story is that the gateway denies tools the policy does not name, and a parameter
    that can quietly switch that off is not a knob worth shipping.
    """
    template["Parameters"].setdefault(
        "PolicyValidationMode",
        {
            "Type": "String",
            "Default": "IGNORE_ALL_FINDINGS",
            "AllowedValues": ["IGNORE_ALL_FINDINGS", "FAIL_ON_ANY_FINDINGS"],
            "Description": (
                "How strictly AgentCore validates the Cedar policies this stack creates. "
                "IGNORE_ALL_FINDINGS, the default, still gets you a default-deny engine whose "
                "policies name every permitted tool explicitly; it skips the advisory findings "
                "analysis, not the rejections that matter (a wildcard resource and a "
                "non-existent gateway are refused in both modes). FAIL_ON_ANY_FINDINGS turns "
                "any finding into a failed stack, including a finding about a Cedar statement "
                "you supplied yourself, which is why it is not the default. Both modes work: "
                "the role that creates the policies is granted bedrock-agentcore:InvokeGateway "
                "on this stack's own gateway, without which CreatePolicy fails in EITHER mode "
                "with 'Insufficient permissions to call gateway'. See README > Authorization "
                "for what that grant allows."
            ),
        },
    )


LAMBDA_VPC_CONDITION = "HasLambdaVpcConfig"


def _apply_lambda_vpc_config(template: dict) -> list[str]:
    """Let the recipient place this stack's Lambdas in their own VPC.

    Every emitted Lambda ran outside any VPC, on the AWS-managed network, with
    unrestricted egress to the internet. For most recipients that is fine. For a
    regulated one it is disqualifying: their controls require the function to sit in
    a private subnet behind their own security group so egress is least-privilege
    (ARCC cnt_dh50RmkA8h91jK: tightly restrict outbound traffic and justify each
    destination; cnt_h4bRcEdetHM9Jv: reach AWS services over VPC endpoints). There
    was no parameter to express it, so their only options were to fork the template
    or not deploy.

    Both parameters default to empty and the condition then resolves to
    ``AWS::NoValue``, so an existing stack is unchanged by this — a recipient who
    does not care sees no difference.

    Deliberately no emitted security group and no emitted subnets. A default group
    would have to allow egress to something, and anything permissive enough to work
    is exactly what the recipients who want this are trying to prevent; anything
    tight enough to satisfy them depends on their endpoint layout, which we cannot
    know. So the customer supplies both, and the README says what access the
    functions actually need.
    """
    template.setdefault("Conditions", {})[LAMBDA_VPC_CONDITION] = {
        "Fn::Not": [{"Fn::Equals": [{"Fn::Join": ["", {"Ref": "LambdaSubnetIds"}]}, ""]}]
    }
    touched = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::Lambda::Function":
            continue
        resource.setdefault("Properties", {})["VpcConfig"] = {
            "Fn::If": [
                LAMBDA_VPC_CONDITION,
                {
                    "SubnetIds": {"Ref": "LambdaSubnetIds"},
                    "SecurityGroupIds": {"Ref": "LambdaSecurityGroupIds"},
                },
                {"Ref": "AWS::NoValue"},
            ]
        }
        touched.append(logical_id)

    # A VPC-attached function creates an elastic network interface in the subnet,
    # and it is the *execution role* that must be allowed to, not the deploying
    # principal. AWSLambdaBasicExecutionRole does not grant it, so without this the
    # function would be created and then fail every invocation with
    # "The provided execution role does not have permissions to call
    # CreateNetworkInterface on EC2" — a runtime error, after a green stack.
    # AWS's own AWSLambdaVPCAccessExecutionRole is the documented grant and is a
    # superset of the basic one; it is attached only under the same condition so a
    # recipient who does not use a VPC gains no ec2 permissions at all.
    # NOT the managed AWSLambdaVPCAccessExecutionRole: it also grants logs:CreateLogGroup
    # on *, which is exactly how a Lambda recreates its declared log group after
    # CloudFormation deleted it (see _apply_lambda_log_groups). The ENI verbs it grants
    # are emitted inline instead, under the same condition, and nothing about logs.
    for role_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::IAM::Role":
            continue
        statements = resource.get("Properties", {}).get("AssumeRolePolicyDocument", {}).get("Statement", [])
        if not any(s.get("Principal", {}).get("Service") == "lambda.amazonaws.com" for s in statements):
            continue
        policies = resource["Properties"].setdefault("Policies", [])
        policy_name = f"VpcEni{role_id}"
        already = any(
            isinstance(pol, dict)
            and "Fn::If" in pol
            and isinstance(pol["Fn::If"][1], dict)
            and pol["Fn::If"][1].get("PolicyName") == policy_name
            for pol in policies
        )
        if not already:
            policies.append(
                {
                    "Fn::If": [
                        LAMBDA_VPC_CONDITION,
                        {
                            "PolicyName": policy_name,
                            "PolicyDocument": {
                                "Version": "2012-10-17",
                                "Statement": [
                                    {
                                        "Sid": policy_name,
                                        "Effect": "Allow",
                                        # What AWSLambdaVPCAccessExecutionRole grants for ENIs. The ec2
                                        # ENI verbs are account-wide by design (no resource ARN shape).
                                        "Action": [
                                            "ec2:CreateNetworkInterface",
                                            "ec2:DescribeNetworkInterfaces",
                                            "ec2:DescribeSubnets",
                                            "ec2:DeleteNetworkInterface",
                                            "ec2:AssignPrivateIpAddresses",
                                            "ec2:UnassignPrivateIpAddresses",
                                        ],
                                        "Resource": "*",
                                    }
                                ],
                            },
                        },
                        {"Ref": "AWS::NoValue"},
                    ]
                }
            )
    return sorted(touched)


def _apply_lambda_log_groups(template: dict) -> list[str]:
    """Give every Lambda in this stack an owned log group with a retention limit.

    Two defects, one fix. A Lambda with no log group resource creates
    ``/aws/lambda/<function>`` itself on first invocation, which means the group is
    not part of the stack: ``cloudformation delete-stack`` leaves it behind, and it
    keeps its logs for ever because CloudWatch Logs retains indefinitely by default
    (ARCC cnt_qf7wYkuSRSM5fl: set a retention limit via CloudFormation). Deploying and
    tearing down repeatedly therefore accumulates log groups nobody owns, holding
    whatever the agent's inputs contained, indefinitely.

    The group name is deliberately NOT the default ``/aws/lambda/<function>``. Adding
    a log group resource under the default name to a stack whose Lambda has already
    run fails the update with "already exists" — the group exists but belongs to
    nobody, so CloudFormation cannot adopt it. Naming it under the stack means no
    *existing* deployment has such a group, so this is safe to add to a stack already in
    service; ``LoggingConfig.LogGroup`` points the function at it. The roles authorize
    ``log-group:*`` in this account and region (see _log_group_resources), so no role
    change is needed.

    That does NOT make the name unused for ever, which an earlier version of this comment
    claimed. Measured live on 15 of 15 torn-down stacks: the provider Lambda goes on
    logging after sending its CFN response, so Lambda recreates
    ``/aws/lambda/<stack>/CfnProviderLambda`` seconds after CloudFormation deleted it —
    without retention, and outside any stack. And not with a tail of the run either: one
    such group, created 27s after DELETE_COMPLETE, held 32 events from ``INIT_START`` and
    the Create-phase lines onward. Redeploying at the same stack name then
    fails at ``[AWS::EarlyValidation::ResourceExistenceCheck]``. Nothing in a template can
    prevent that; the generated ``teardown.sh`` sweeps it instead, see
    _TEARDOWN_LOG_GROUP_SWEEP_SH.

    ``KmsKeyId`` is not set here either: ``AWS::Logs::LogGroup`` is in
    CUSTOMER_KEY_PROPERTIES, so ``_apply_customer_key`` sets it under the same
    opt-in condition as everything else. That pass has to run after this one.
    """
    touched = []
    for logical_id in [
        lid for lid, r in template.get("Resources", {}).items() if r.get("Type") == "AWS::Lambda::Function"
    ]:
        group_id = f"{logical_id}LogGroup"
        if group_id in template["Resources"]:
            continue
        template["Resources"][group_id] = {
            "Type": "AWS::Logs::LogGroup",
            # No DeletionPolicy here: AWS::Logs::LogGroup is in
            # DATA_BEARING_RESOURCE_TYPES, so _apply_data_retention stamps it with
            # whatever the recipient chose. This pass therefore has to run *before*
            # that one — see the call order in generate().
            "Properties": {
                "LogGroupName": {"Fn::Sub": f"/aws/lambda/${{AWS::StackName}}/{logical_id}"},
                "RetentionInDays": {"Ref": "LogRetentionInDays"},
            },
        }
        function = template["Resources"][logical_id]
        function.setdefault("Properties", {})["LoggingConfig"] = {"LogGroup": {"Ref": group_id}}
        # The function's role must NOT be able to create log groups. With a declared group
        # (LoggingConfig above) the only thing logs:CreateLogGroup can do is recreate that
        # group after CloudFormation deleted it -- which a final invocation on teardown
        # would, leaving residue that a direct delete-stack or terraform destroy never
        # sweeps (measured: /aws/lambda/<stack>/CfnProviderLambda came back seconds after
        # its deletion). AWSLambdaBasicExecutionRole grants CreateLogGroup on *; replace
        # it with CreateLogStream/PutLogEvents on this function's own group and nothing else.
        role_ref = function.get("Properties", {}).get("Role")
        role_id = role_ref.get("Fn::GetAtt", [None])[0] if isinstance(role_ref, dict) else None
        role = template["Resources"].get(role_id) if role_id else None
        if role and role.get("Type") == "AWS::IAM::Role":
            props = role.setdefault("Properties", {})
            managed = [m for m in props.get("ManagedPolicyArns", []) if "AWSLambdaBasicExecutionRole" not in str(m)]
            if managed:
                props["ManagedPolicyArns"] = managed
            else:
                props.pop("ManagedPolicyArns", None)
            sid = f"OwnLogStreams{logical_id}"
            policies = props.setdefault("Policies", [])
            if not any(isinstance(pol, dict) and pol.get("PolicyName") == sid for pol in policies):
                policies.append(
                    {
                        "PolicyName": sid,
                        "PolicyDocument": {
                            "Version": "2012-10-17",
                            "Statement": [
                                {
                                    "Sid": sid,
                                    "Effect": "Allow",
                                    "Action": ["logs:CreateLogStream", "logs:PutLogEvents"],
                                    "Resource": {
                                        "Fn::Sub": f"arn:${{AWS::Partition}}:logs:${{AWS::Region}}:${{AWS::AccountId}}:log-group:/aws/lambda/${{AWS::StackName}}/{logical_id}:*"
                                    },
                                }
                            ],
                        },
                    }
                )
        # LoggingConfig's Ref already gives CloudFormation the exact creation
        # dependency. An additional DependsOn is redundant and makes cfn-lint
        # report W3005 on every generated Lambda.
        touched.append(logical_id)
    return sorted(touched)


def _runtime_endpoint_qualifier(name: object, endpoint_id: str) -> str:
    """An endpoint's ``Name`` as text that can sit inside an outer ``Fn::Sub``.

    Flattened rather than nested on purpose: ``Fn::Sub``'s variable map accepts
    ``Ref`` and ``Fn::GetAtt`` but NOT another ``Fn::Sub``, and the inner string's
    ``${DeploymentName}`` resolves identically when it is inlined into the outer one.

    Anything else raises. The alternative — skipping a shape this cannot flatten —
    would silently leave that endpoint's log group with no retention and no key,
    which is the exact defect this whole pass exists to fix, and it would leave it
    with no failing test either.
    """
    if isinstance(name, str):
        return name
    if isinstance(name, dict) and isinstance(name.get("Fn::Sub"), str):
        return name["Fn::Sub"]
    raise ValueError(
        f"runtime endpoint {endpoint_id} has a Name this generator cannot turn into a log "
        f"group name ({name!r}); Custom::RuntimeLogGroup would leave its logs ungoverned"
    )


def _apply_runtime_log_groups(template: dict) -> list[str]:
    """Govern the log groups AgentCore creates for each runtime it is asked to run.

    ``AWS::BedrockAgentCore::Runtime`` has no logging properties whatsoever, so
    nothing in the emitted template reached these groups: the service created
    ``/aws/bedrock-agentcore/runtimes/<runtimeId>-<qualifier>`` itself, with no
    retention limit and the AWS-owned key, and a ``delete-stack`` left it behind. That
    is the agent's conversation — what it was asked and what it answered — kept for
    ever, unencrypted by the customer's key, in a group no stack owns. ARCC
    cnt_sSTfcrsdyTSviN item 6 requires customer content to have a retention period and
    item 8 requires customer-managed-key support so the customer controls it; ARCC
    cnt_qf7wYkuSRSM5fl requires the retention limit to be set through CloudFormation.
    The same two knobs already cover the Lambda groups (see _apply_lambda_log_groups);
    this is the resource that could not be declared.

    Declaring them as ``AWS::Logs::LogGroup`` is not an option, which is why this is a
    custom resource: the runtime creates the groups during the stack's own create, so a
    declared group of the same name collides with one that already exists and belongs
    to nobody. The handler creates-or-adopts; it deletes only when CloudFormation sends
    Delete, which the retention stamping confines to a failed first create, a replaced
    runtime under Delete, or a Delete-mode teardown (see _apply_data_retention).

    ONE RESOURCE PER LOG GROUP, not one per runtime. The service makes a group per
    endpoint plus ``-DEFAULT`` — proven live on a runtime with one named endpoint, which
    had both — and the named one is where an invoke against that qualifier writes. Each
    group gets its own ``Custom::RuntimeLogGroup`` whose physical id the handler derives
    from the group name, so a replaced runtime (new runtime id => new names) REPLACES
    exactly the affected resources: CloudFormation then deletes the old ones only after
    the update has stabilized and only under ``UpdateReplacePolicy: Delete``, a failed
    update's rollback removes the NEW groups and keeps the old audit trail, and adding
    or renaming an endpoint never touches the shared ``-DEFAULT`` group. A single
    multi-group resource could not honor any of that: its id was stable across updates,
    so a replacement merely re-pointed it and the old runtime's groups were orphaned.

    The ``-DEFAULT`` resource keeps the historical logical id ``<Runtime>LogGroups`` so
    an existing stack is UPDATED in place when it picks up this template; removing that
    logical id would make CloudFormation send it a Delete — which now really deletes.

    Deletion ORDER is the last problem. Every per-group resource GetAtts its runtime, so
    CloudFormation deletes it BEFORE the runtime, while AgentCore is still alive and can
    write final events -- recreating a group the provider had just deleted (the same
    class as Lambda recreating its log group after a teardown). So each runtime also
    gets a ``Mode: sweeper`` resource that the RUNTIME depends on: created first,
    deleted last. The per-group resources each record their resolved name as ONE SSM
    parameter under ``/agentcore-cfn/<stack>/<stack-id-digest>/<runtime>/<generation>/groups/``
    (one entry per group -- no shared document to race on; the stack-id digest keeps a
    same-name redeploy apart from a retained predecessor; the generation is a digest of
    the runtime's replacement property, AgentRuntimeName). On Delete the sweeper reads
    its generation's entries and, if there are none, recovers the runtime id from
    CloudFormation's own record of the runtime resource -- refusing unless that id
    carries this generation's name -- and lists the groups by prefix, because a runtime
    can create groups and fail before any governance resource recorded them. It deletes
    each group, waits, re-checks until nothing comes back, then removes the entries. Same
    retention stamping as the groups, so a retained stack's deletion skips it and the
    audit trail survives.
    """
    resources = template.get("Resources", {})
    added: list[str] = []

    def _generation(runtime_id: str) -> str:
        # AgentRuntimeName is the runtime's replacement property. A sweeper whose id
        # carries a digest of that (static) template value is REPLACED when the name
        # changes, so the OLD sweeper is deleted after the OLD runtime and sweeps the old
        # runtime's groups; the new one takes over the new runtime.
        name = resources[runtime_id].get("Properties", {}).get("AgentRuntimeName")
        return hashlib.sha256(json.dumps(name, sort_keys=True).encode("utf-8")).hexdigest()[:12]

    def _sweeper_resource(runtime_id: str) -> dict:
        # No Fn::GetAtt on the runtime and no DependsOn: the RUNTIME depends on this, so it
        # is created first and deleted last -- after AgentCore has stopped writing.
        return {
            "Type": "Custom::RuntimeLogGroup",
            "Properties": {
                "ServiceToken": {"Fn::GetAtt": ["CfnProviderLambda", "Arn"]},
                "Mode": "sweeper",
                "RuntimeLogicalId": runtime_id,
                "Generation": _generation(runtime_id),
                # The static name, so the sweeper can prove a runtime id it recovers from
                # CloudFormation belongs to THIS generation (ids are "<name>-<suffix>").
                "AgentRuntimeName": resources[runtime_id]["Properties"]["AgentRuntimeName"],
            },
        }

    def _group_resource(runtime_id: str, qualifier) -> dict:
        # GetAtts the runtime (deleted before it) and nothing else. Endpoint governance
        # resources are depended upon BY their endpoint, so the endpoint deletes first.
        return {
            "Type": "Custom::RuntimeLogGroup",
            "Properties": {
                "ServiceToken": {"Fn::GetAtt": ["CfnProviderLambda", "Arn"]},
                "RuntimeLogicalId": runtime_id,
                "Generation": _generation(runtime_id),
                "LogGroupNames": [
                    {
                        "Fn::Sub": [
                            f"{RUNTIME_LOG_GROUP_PREFIX}/${{RuntimeId}}-{qualifier}",
                            {"RuntimeId": {"Fn::GetAtt": [runtime_id, "AgentRuntimeId"]}},
                        ]
                    }
                ],
                "RetentionInDays": {"Ref": "LogRetentionInDays"},
            },
        }

    def _add_dependency(logical_id: str, on: str) -> None:
        res = template["Resources"][logical_id]
        depends = res.get("DependsOn") or []
        depends = [depends] if isinstance(depends, str) else list(depends)
        if on not in depends:
            res["DependsOn"] = depends + [on]

    for runtime_id in sorted(lid for lid, r in resources.items() if r.get("Type") == "AWS::BedrockAgentCore::Runtime"):
        sweeper_id = f"{runtime_id}LogGroupSweeper"
        if sweeper_id not in resources:
            template["Resources"][sweeper_id] = _sweeper_resource(runtime_id)
            added.append(sweeper_id)
        _add_dependency(runtime_id, sweeper_id)
        default_id = f"{runtime_id}LogGroups"  # historical id: the DEFAULT group's resource
        if default_id not in resources:
            template["Resources"][default_id] = _group_resource(runtime_id, "DEFAULT")
            added.append(default_id)
        for endpoint_id, endpoint in sorted(resources.items()):
            if endpoint.get("Type") != "AWS::BedrockAgentCore::RuntimeEndpoint":
                continue
            runtime_ref = endpoint.get("Properties", {}).get("AgentRuntimeId")
            get_att = runtime_ref.get("Fn::GetAtt") if isinstance(runtime_ref, dict) else None
            if not get_att or get_att[0] != runtime_id:
                continue
            logical_id = f"{runtime_id}LogGroup{endpoint_id}"
            if logical_id not in resources:
                qualifier = _runtime_endpoint_qualifier(endpoint["Properties"].get("Name"), endpoint_id)
                template["Resources"][logical_id] = _group_resource(runtime_id, qualifier)
                added.append(logical_id)
            _add_dependency(endpoint_id, logical_id)  # the endpoint deletes BEFORE its group governance
    return added


def _gateway_invoke_permission(function_logical_id: str) -> dict:
    """Let the AgentCore Gateway invoke *function_logical_id*, and nobody else's.

    Checkov CKV_AWS_364 on the emitted template: all three of these permissions
    named the ``bedrock-agentcore.amazonaws.com`` service principal with neither
    ``SourceAccount`` nor ``SourceArn``. A service-principal grant with no source
    constraint is the textbook confused deputy — it authorizes AgentCore acting for
    *any* AWS account, so somebody else's gateway configured against this function's
    ARN would be allowed to invoke it. The KB tool Lambda holds ``bedrock:Retrieve``
    on this account's knowledge base, so that is a read path into it.

    ``SourceAccount`` and not ``SourceArn``: the gateway ARN would be the tighter
    constraint, but the AgentCore resource types publish no ``Arn`` attribute this
    generator has verified, and cfn-lint ships no schema for them to catch a wrong
    ``Fn::GetAtt``. Account scoping is what can be asserted, and it closes the
    cross-account path, which is the actual threat.

    One helper for all three call sites rather than three identical dicts, so a
    fourth Lambda target cannot be added without the constraint.
    """
    return {
        "Type": "AWS::Lambda::Permission",
        "Properties": {
            "FunctionName": {"Fn::GetAtt": [function_logical_id, "Arn"]},
            "Action": "lambda:InvokeFunction",
            "Principal": "bedrock-agentcore.amazonaws.com",
            "SourceAccount": {"Ref": "AWS::AccountId"},
        },
    }


class CfnExportUnsupportedError(ValueError):
    """The canvas is valid but this exporter cannot represent it faithfully.

    Distinct from a bug: the deploy would succeed on the live Step Functions
    path, and refusing is the correct answer only because emitting a template
    anyway would emit the *wrong* stack. Callers should surface the message to
    the user as a 4xx — it is written to be actionable, not internal.

    Subclasses ``ValueError`` deliberately. Several of these refusals were first
    written as bare ``raise ValueError`` (the unconstrained-permit and
    no-nameable-tool policy checks), and callers/tests catch them as ValueError.
    Being both lets the API map every one to an actionable 400 via a single
    ``except CfnExportUnsupportedError`` — which is matched before any broad
    ``except Exception`` — while those historical ValueError catches keep working.
    The generate() call chain has no intervening ``except ValueError``, so
    widening the type here cannot silently swallow a refusal that used to
    surface.
    """


# ---------------------------------------------------------------------------
# Customer naming profiles
# ---------------------------------------------------------------------------

# A JSON request cannot carry the Python naming callback originally suggested by
# customers. This declarative profile is the API-safe equivalent: every semantic
# resource family has one template, callers can override any subset, and a single
# pass applies the same resolved names to resources, OAuth scopes, outputs, log
# qualifiers and IAM grants. Keeping those consumers together is the correctness
# property; changing a resource name without its ARN grant produces a stack that
# deploys successfully and then fails only when invoked.
_NAMING_PROFILE_TEMPLATES: dict[str, str] = {
    "cognitoUserPool": "{prefix}-{deployment}",
    "cognitoResourceServer": "{prefix}-{deployment}",
    "cognitoClient": "{prefix}-{deployment}-client",
    "cognitoDomain": "{prefix}-{deployment}-{suffix}",
    "gateway": "{prefix}-{deployment}-gateway",
    "gatewayTarget": "{prefix}-{deployment}-{component}",
    "toolLambda": "{prefix}-{deployment}-{component}",
    "customToolLambda": "{prefix}-{deployment}-ct-{component}",
    "knowledgeBase": "{prefix}-{deployment}-kb",
    "knowledgeBaseDataSource": "{prefix}-{deployment}-kb-ds",
    "knowledgeBaseToolLambda": "{prefix}-{deployment}-kb-tool",
    "vectorBucket": "{prefix}-{deployment}-kbvec-{suffix}",
    "vectorIndex": "{prefix}-{deployment}-kb-index",
    "memory": "{prefix}_{deployment}_memory",
    "policyEngine": "{prefix}_{deployment}_policy_engine",
    "policy": "{prefix}_{deployment}_{component}",
    "mcpCognitoUserPool": "{prefix}-mcp-{deployment}",
    "mcpCognitoResourceServer": "{prefix}-mcp-{deployment}",
    "mcpCognitoClient": "{prefix}-mcp-{deployment}-client",
    "mcpCognitoDomain": "{prefix}-mcp-{deployment}-{suffix}",
    "mcpCredentialProvider": "{prefix}-mcp-cred-{deployment}",
    "mcpRuntime": "{prefix}_{deployment}_mcp_server",
    "mcpEndpoint": "{prefix}_{deployment}_mcp_endpoint",
    "evaluation": "{prefix}_{deployment}_evaluation",
    "guardrail": "{prefix}-{deployment}-guardrail",
    "runtime": "{prefix}_{deployment}_runtime",
    "runtimeEndpoint": "{prefix}_{deployment}_endpoint",
    "runtimeRole": "{prefix}-{deployment}-{suffix}-runtime-role",
    "gatewayRole": "{prefix}-{deployment}-{suffix}-gateway-role",
    "toolLambdaRole": "{prefix}-{deployment}-{suffix}-lambda-role",
    "knowledgeBaseToolRole": "{prefix}-{deployment}-{suffix}-kb-tool-role",
    "knowledgeBaseRole": "{prefix}-{deployment}-{suffix}-kb-role",
    "memoryRole": "{prefix}-{deployment}-{suffix}-memory-role",
    "mcpRuntimeRole": "{prefix}-{deployment}-{suffix}-mcp-role",
    "evaluationRole": "{prefix}-{deployment}-{suffix}-evaluation-role",
}

_NAMING_PROFILE_REQUIRED_FIELDS: dict[str, frozenset[str]] = {
    key: frozenset({"deployment"}) for key in _NAMING_PROFILE_TEMPLATES
}
for _stack_unique_key in ("cognitoDomain", "mcpCognitoDomain", "vectorBucket"):
    _NAMING_PROFILE_REQUIRED_FIELDS[_stack_unique_key] = frozenset({"deployment", "suffix"})
for _component_key in ("gatewayTarget", "toolLambda", "customToolLambda", "policy"):
    _NAMING_PROFILE_REQUIRED_FIELDS[_component_key] = frozenset({"deployment", "component"})
_NAMING_ROLE_KEYS = frozenset(
    {
        "runtimeRole",
        "gatewayRole",
        "toolLambdaRole",
        "knowledgeBaseToolRole",
        "knowledgeBaseRole",
        "memoryRole",
        "mcpRuntimeRole",
        "evaluationRole",
    }
)
for _role_key in _NAMING_ROLE_KEYS:
    _NAMING_PROFILE_REQUIRED_FIELDS[_role_key] = frozenset({"deployment", "suffix"})

_NAMING_PROFILE_ALLOWED_FIELDS: dict[str, frozenset[str]] = {
    key: frozenset({"prefix", "deployment"}) for key in _NAMING_PROFILE_TEMPLATES
}
for _stack_unique_key in ("cognitoDomain", "mcpCognitoDomain", "vectorBucket"):
    _NAMING_PROFILE_ALLOWED_FIELDS[_stack_unique_key] = frozenset({"prefix", "deployment", "suffix"})
for _component_key in ("gatewayTarget", "toolLambda", "customToolLambda", "policy"):
    _NAMING_PROFILE_ALLOWED_FIELDS[_component_key] = frozenset({"prefix", "deployment", "component"})
for _role_key in _NAMING_ROLE_KEYS:
    _NAMING_PROFILE_ALLOWED_FIELDS[_role_key] = frozenset({"prefix", "deployment", "suffix"})

# Conservative rules common to both the CloudFormation registry schema and the
# current AgentCore control-plane service model. A customer override is rejected at
# export time with its semantic key, instead of surviving until a CreateChangeSet or
# service call reports only an opaque "invalid request".
_NAMING_PROFILE_RULES: dict[str, tuple[int, re.Pattern[str]]] = {
    "cognitoUserPool": (128, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "cognitoResourceServer": (128, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "cognitoClient": (128, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "cognitoDomain": (63, re.compile(r"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$")),
    "gateway": (48, re.compile(r"^(?:[0-9A-Za-z]-?)+$")),
    "gatewayTarget": (100, re.compile(r"^(?:[0-9A-Za-z]-?)+$")),
    "toolLambda": (64, re.compile(r"^[A-Za-z0-9_-]+$")),
    "customToolLambda": (64, re.compile(r"^[A-Za-z0-9_-]+$")),
    "knowledgeBase": (100, re.compile(r"^(?:[0-9A-Za-z][_-]?)+$")),
    "knowledgeBaseDataSource": (100, re.compile(r"^(?:[0-9A-Za-z][_-]?)+$")),
    "knowledgeBaseToolLambda": (64, re.compile(r"^[A-Za-z0-9_-]+$")),
    # S3 Vectors is stricter for buckets than indexes. Its API and CFN schemas
    # currently publish only the 3-63 length range, while the service naming
    # guide additionally limits buckets to lowercase letters, numbers, and
    # hyphens. Dots are valid for an index, not for its vector bucket.
    "vectorBucket": (63, re.compile(r"^[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])$")),
    "vectorIndex": (63, re.compile(r"^[a-z0-9](?:[a-z0-9.-]{1,61}[a-z0-9])$")),
    "memory": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "policyEngine": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "policy": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "mcpCognitoUserPool": (128, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "mcpCognitoResourceServer": (128, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "mcpCognitoClient": (128, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "mcpCognitoDomain": (63, re.compile(r"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$")),
    "mcpCredentialProvider": (128, re.compile(r"^[A-Za-z0-9_-]+$")),
    "mcpRuntime": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "mcpEndpoint": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "evaluation": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "guardrail": (50, re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")),
    "runtime": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "runtimeEndpoint": (48, re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")),
    "runtimeRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "gatewayRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "toolLambdaRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "knowledgeBaseToolRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "knowledgeBaseRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "memoryRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "mcpRuntimeRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
    "evaluationRole": (64, re.compile(r"^[A-Za-z0-9_+=,.@-]+$")),
}

_NAMING_DEPLOYMENT_SAMPLE = "d" * 20
_NAMING_SUFFIX_SAMPLE = "a" * 12


def _profile_template(profile: CfnNamingProfile, key: str) -> tuple[str, frozenset[str]]:
    """Return and structurally validate one naming template."""
    if key not in _NAMING_PROFILE_TEMPLATES:
        raise CfnExportUnsupportedError(f"Unknown naming profile resource family {key!r}.")
    template = profile.resource_names.get(key, _NAMING_PROFILE_TEMPLATES[key])
    try:
        parsed = list(Formatter().parse(template))
    except ValueError as exc:
        raise CfnExportUnsupportedError(f"namingProfile.resourceNames.{key} is not a valid template: {exc}") from exc

    fields: set[str] = set()
    for _literal, field_name, format_spec, conversion in parsed:
        if field_name is None:
            continue
        if format_spec or conversion:
            raise CfnExportUnsupportedError(
                f"namingProfile.resourceNames.{key} may not use format conversions or format specifications"
            )
        if field_name not in _NAMING_PROFILE_ALLOWED_FIELDS[key]:
            allowed = ", ".join(f"{{{name}}}" for name in sorted(_NAMING_PROFILE_ALLOWED_FIELDS[key]))
            raise CfnExportUnsupportedError(
                f"namingProfile.resourceNames.{key} uses unsupported placeholder "
                f"{{{field_name}}}; allowed placeholders are {allowed}"
            )
        fields.add(field_name)

    missing = _NAMING_PROFILE_REQUIRED_FIELDS[key] - fields
    if missing:
        required = ", ".join(f"{{{name}}}" for name in sorted(missing))
        raise CfnExportUnsupportedError(
            f"namingProfile.resourceNames.{key} must include {required} so independently deployed stacks do not collide"
        )
    return template, frozenset(fields)


def _render_profile_name(
    profile: CfnNamingProfile,
    key: str,
    *,
    component: str | None = None,
    suffix: str | None = None,
) -> str:
    """Render one profile value as an ``Fn::Sub`` string and validate its real limits."""
    template, fields = _profile_template(profile, key)
    if "component" in fields and component is None:
        component = "component"
    if "suffix" in fields and suffix is None:
        suffix = "${StackSuffix}"

    values = {
        "prefix": profile.prefix,
        "deployment": "${DeploymentName}",
        "component": component or "",
        "suffix": suffix or "",
    }
    sample_values = {
        **values,
        "deployment": _NAMING_DEPLOYMENT_SAMPLE,
        "suffix": _NAMING_SUFFIX_SAMPLE if "suffix" in fields else "",
    }

    max_length, pattern = _NAMING_PROFILE_RULES[key]

    # Tool names are user-controlled and can be 32 characters before this pass.
    # Preserve them when they fit; if a prefix makes the Lambda's 64-character
    # ceiling tighter, use a stable hash tail rather than silently dropping the
    # distinguishing end and creating collisions.
    original_component = sample_values["component"]
    if "component" in fields and original_component:
        digest = hashlib.sha256(original_component.encode()).hexdigest()[:8]
        hash_separator = "_" if key == "policy" else "-"
        for target_length in range(len(original_component), 0, -1):
            if target_length == len(original_component):
                candidate = original_component
            elif target_length > len(digest) + 1:
                candidate = original_component[: target_length - len(digest) - 1] + hash_separator + digest
            else:
                candidate = digest[:target_length]
            sample_values["component"] = candidate
            candidate_name = template.format(**sample_values)
            if len(candidate_name) <= max_length and pattern.fullmatch(candidate_name):
                values["component"] = candidate
                break

    try:
        rendered = template.format(**values)
        sample = template.format(**sample_values)
        minimum_sample = template.format(
            **{
                **sample_values,
                "deployment": "d",
            }
        )
    except (KeyError, ValueError) as exc:
        raise CfnExportUnsupportedError(f"namingProfile.resourceNames.{key} could not be rendered: {exc}") from exc

    if len(sample) > max_length:
        raise CfnExportUnsupportedError(
            f"namingProfile.resourceNames.{key} produces {len(sample)} characters at the "
            f"supported 20-character DeploymentName limit; AWS permits at most {max_length}. "
            "Shorten the prefix or this template."
        )
    if not pattern.fullmatch(sample):
        raise CfnExportUnsupportedError(
            f"namingProfile.resourceNames.{key} produces {sample!r}, which is not valid for "
            "that AWS resource family. Use only the separators that service accepts."
        )
    if not pattern.fullmatch(minimum_sample):
        raise CfnExportUnsupportedError(
            f"namingProfile.resourceNames.{key} produces {minimum_sample!r} for a "
            "1-character DeploymentName, which is not valid for that AWS resource "
            "family. Keep enough fixed text in the template to satisfy its minimum "
            "length and naming grammar."
        )
    return rendered


def _profile_cognito_domain(profile: CfnNamingProfile, key: str) -> dict:
    """Build the two suffix branches of a profile-aware Cognito domain."""
    return {
        "Fn::If": [
            COGNITO_DOMAIN_SUFFIX_CONDITION,
            {"Fn::Sub": _render_profile_name(profile, key, suffix="${CognitoDomainSuffix}")},
            {
                "Fn::Sub": [
                    _render_profile_name(profile, key, suffix="${StackSuffix}"),
                    {"StackSuffix": _stack_id_suffix()},
                ]
            },
        ]
    }


def _profile_stack_unique_name(profile: CfnNamingProfile, key: str) -> dict:
    """A readable physical name that stays unique when stacks share DeploymentName."""
    return {
        "Fn::Sub": [
            _render_profile_name(profile, key, suffix="${StackSuffix}"),
            {"StackSuffix": _stack_id_suffix()},
        ]
    }


def _bounded_deployment_default(value: str, max_length: int) -> str:
    """Fit a deployment default without clipping distinct names into collisions."""
    if len(value) <= max_length:
        return value
    digest = hashlib.sha256(value.encode()).hexdigest()[:8]
    if max_length <= len(digest):
        # All current resource combinations leave at least 18 characters, but keep
        # this helper total if a future service introduces a much smaller limit.
        return "a" + digest[: max_length - 1]
    return value[: max_length - len(digest)] + digest


def _bounded_identifier_component(value: str, max_length: int) -> str:
    """Shorten one identifier component with a stable, collision-resistant tail."""
    if len(value) <= max_length:
        return value
    digest = hashlib.sha256(value.encode()).hexdigest()[:8]
    if max_length <= len(digest):
        return digest[:max_length]
    return value[: max_length - len(digest) - 1] + "_" + digest


def _profile_deployment_default(value: str) -> str:
    """Keep a 20-character profile default collision-resistant."""
    return _bounded_deployment_default(value, 20)


# Physical-name properties that may contain ``${DeploymentName}``, mapped to the
# same service family rules used by customer naming profiles. The no-profile path
# historically admitted 40 characters unconditionally. That cannot deploy for
# every canvas: ``${DeploymentName}_endpoint`` already reaches 49 characters, an
# MCP endpoint reaches 53, and a long custom-tool Lambda reaches 86. A recipient
# using Terraform or CloudFormation directly could therefore pass template
# validation and roll back later even though deploy.sh happened to clip to 20.
#
# Deriving the ceiling from the emitted resources preserves every ordinary legacy
# name. A runtime-only template can still use 39 characters; a canvas whose actual
# tool suffix needs more room receives a smaller, honest limit.
_NAMING_PROPERTY_FAMILIES: dict[tuple[str, str], str] = {
    ("AWS::Cognito::UserPool", "UserPoolName"): "cognitoUserPool",
    ("AWS::Cognito::UserPoolResourceServer", "Identifier"): "cognitoResourceServer",
    ("AWS::Cognito::UserPoolResourceServer", "Name"): "cognitoResourceServer",
    ("AWS::Cognito::UserPoolClient", "ClientName"): "cognitoClient",
    ("AWS::Cognito::UserPoolDomain", "Domain"): "cognitoDomain",
    ("AWS::BedrockAgentCore::Gateway", "Name"): "gateway",
    ("AWS::BedrockAgentCore::GatewayTarget", "Name"): "gatewayTarget",
    ("AWS::Lambda::Function", "FunctionName"): "toolLambda",
    ("AWS::Bedrock::KnowledgeBase", "Name"): "knowledgeBase",
    ("AWS::Bedrock::DataSource", "Name"): "knowledgeBaseDataSource",
    ("AWS::S3Vectors::VectorBucket", "VectorBucketName"): "vectorBucket",
    ("AWS::S3Vectors::Index", "IndexName"): "vectorIndex",
    ("AWS::BedrockAgentCore::Memory", "Name"): "memory",
    ("AWS::BedrockAgentCore::PolicyEngine", "Name"): "policyEngine",
    ("Custom::AgentCorePolicy", "Name"): "policy",
    ("Custom::OAuth2CredentialProvider", "ProviderName"): "mcpCredentialProvider",
    ("AWS::BedrockAgentCore::Runtime", "AgentRuntimeName"): "runtime",
    ("AWS::BedrockAgentCore::RuntimeEndpoint", "Name"): "runtimeEndpoint",
    (
        "AWS::BedrockAgentCore::OnlineEvaluationConfig",
        "OnlineEvaluationConfigName",
    ): "evaluation",
    ("AWS::Bedrock::Guardrail", "Name"): "guardrail",
}

_SUB_PLACEHOLDER_MAX_LENGTHS = {
    "AWS::AccountId": 12,
    "AWS::Partition": 10,
    "AWS::Region": 32,
    "AWS::StackName": 128,
    "StackSuffix": 12,
    "CognitoDomainSuffix": 12,
}


def _name_expression_templates(value) -> list[str]:
    """Return every possible string template from a name property's intrinsics."""
    if isinstance(value, str):
        return [value]
    if not isinstance(value, dict):
        return []
    substitution = value.get("Fn::Sub")
    if isinstance(substitution, str):
        return [substitution]
    if isinstance(substitution, list) and substitution and isinstance(substitution[0], str):
        return [substitution[0]]
    conditional = value.get("Fn::If")
    if isinstance(conditional, list) and len(conditional) == 3:
        return [expression for branch in conditional[1:] for expression in _name_expression_templates(branch)]
    return []


def _contains_sub_placeholder(value, placeholder: str) -> bool:
    """Whether an arbitrarily nested intrinsic value mentions one placeholder."""
    if isinstance(value, str):
        return f"${{{placeholder}}}" in value
    if isinstance(value, dict):
        return any(
            _contains_sub_placeholder(key, placeholder) or _contains_sub_placeholder(item, placeholder)
            for key, item in value.items()
        )
    if isinstance(value, list):
        return any(_contains_sub_placeholder(item, placeholder) for item in value)
    return False


def _render_name_limit_sample(
    expression: str,
    deployment_length: int,
    *,
    stack_name_length: int | None = None,
) -> str:
    """Render enough of an Fn::Sub expression to check its service name limit."""

    def replace(match: re.Match[str]) -> str:
        placeholder = match.group(1)
        if placeholder == "DeploymentName":
            return "d" * deployment_length
        if placeholder == "AWS::StackName" and stack_name_length is not None:
            return "s" * stack_name_length
        return "a" * _SUB_PLACEHOLDER_MAX_LENGTHS.get(placeholder, 128)

    return re.sub(r"\$\{([^}]+)\}", replace, expression)


def _legacy_deployment_name_limit(template: dict) -> int:
    """Tightest deployable ``DeploymentName`` length for this emitted resource set."""
    capacities = [40]
    for logical_id, resource in template.get("Resources", {}).items():
        properties = resource.get("Properties", {})
        resource_type = resource.get("Type")
        for (mapped_type, property_name), family in _NAMING_PROPERTY_FAMILIES.items():
            if resource_type != mapped_type or property_name not in properties:
                continue
            max_length, pattern = _NAMING_PROFILE_RULES[family]
            property_value = properties[property_name]
            expressions = _name_expression_templates(property_value)
            if _contains_sub_placeholder(property_value, "DeploymentName") and not expressions:
                raise CfnExportUnsupportedError(
                    f"{logical_id}.{property_name} contains DeploymentName in an "
                    "intrinsic form the legacy name-limit calculator does not "
                    "understand. Refusing the export prevents that name from "
                    "bypassing its AWS service limit."
                )
            for expression in expressions:
                occurrences = expression.count("${DeploymentName}")
                if not occurrences:
                    continue
                without_deployment = _render_name_limit_sample(expression, 0)
                capacity = (max_length - len(without_deployment)) // occurrences
                if capacity < 1:
                    raise CfnExportUnsupportedError(
                        f"{logical_id}.{property_name} leaves no valid room for DeploymentName "
                        f"under the {family} {max_length}-character service limit."
                    )
                sample = _render_name_limit_sample(expression, capacity)
                if not pattern.fullmatch(sample):
                    raise CfnExportUnsupportedError(
                        f"{logical_id}.{property_name} produces {sample!r}, which is not valid "
                        f"for the {family} resource family."
                    )
                minimum_sample = _render_name_limit_sample(expression, 1)
                if not pattern.fullmatch(minimum_sample):
                    raise CfnExportUnsupportedError(
                        f"{logical_id}.{property_name} produces {minimum_sample!r} for a "
                        "1-character DeploymentName, which is not valid for the "
                        f"{family} resource family."
                    )
                capacities.append(capacity)
    return min(capacities)


def _apply_legacy_deployment_name_limit(template: dict) -> None:
    """Make the no-profile parameter and its generated default honestly deployable."""
    max_length = _legacy_deployment_name_limit(template)
    parameter = template["Parameters"]["DeploymentName"]
    parameter.update(
        {
            "Default": _bounded_deployment_default(
                str(parameter.get("Default", "agentcore")),
                max_length,
            ),
            "MaxLength": max_length,
            # Preserve the legacy public regex contract. MaxLength is the
            # component-specific second half of validation and is what prevents
            # a value accepted by this broad grammar from overflowing one of the
            # physical names in this particular export.
            "AllowedPattern": "^[a-z][a-z0-9]{0,39}$",
            "ConstraintDescription": (
                "Lowercase alphanumeric only, no hyphens/underscores, "
                f"1-{max_length} chars, must start with a letter. This limit is "
                "derived from the physical names in this export so every accepted "
                "value remains within its AWS service limit."
            ),
            "Description": (
                "Base name for all resources (lowercase alphanumeric only; "
                f"1-{max_length} characters for this component set)"
            ),
        }
    )


def _explicit_role_stack_name_limit(template: dict) -> int | None:
    """Longest stack name that fits every explicit IAM ``RoleName`` branch.

    Legacy role names interpolate ``AWS::StackName``, which is independent of the
    bounded ``DeploymentName`` parameter. CloudFormation permits a 128-character
    stack name while IAM permits a 64-character role name, so deploy.sh needs a
    separate guard. Profile-derived roles use DeploymentName plus StackSuffix and
    therefore return ``None`` here.
    """
    max_length, pattern = _NAMING_PROFILE_RULES["runtimeRole"]
    capacities: list[int] = []
    for logical_id, resource in template.get("Resources", {}).items():
        if resource.get("Type") != "AWS::IAM::Role":
            continue
        role_name = resource.get("Properties", {}).get("RoleName")
        for expression in _name_expression_templates(role_name):
            occurrences = expression.count("${AWS::StackName}")
            if not occurrences:
                continue
            without_stack = _render_name_limit_sample(
                expression,
                deployment_length=0,
                stack_name_length=0,
            )
            capacity = (max_length - len(without_stack)) // occurrences
            if capacity < 1:
                raise CfnExportUnsupportedError(
                    f"{logical_id}.RoleName leaves no valid room for AWS::StackName "
                    f"under IAM's {max_length}-character role-name limit."
                )
            sample = _render_name_limit_sample(
                expression,
                deployment_length=0,
                stack_name_length=capacity,
            )
            if not pattern.fullmatch(sample):
                raise CfnExportUnsupportedError(
                    f"{logical_id}.RoleName produces {sample!r}, which is not a valid IAM role name."
                )
            capacities.append(capacity)
    return min(capacities) if capacities else None


def _apply_explicit_role_stack_name_guidance(template: dict) -> int | None:
    """Record the explicit-role stack-name ceiling in the parameter contract."""
    limit = _explicit_role_stack_name_limit(template)
    if limit is None:
        return None
    parameter = template.get("Parameters", {}).get("UseExplicitRoleNames")
    if parameter is not None:
        parameter["Description"] = (
            "true keeps the readable AgentCore*-<stack> role names and requires "
            "CAPABILITY_NAMED_IAM; it is valid only when the CloudFormation stack "
            f"name is at most {limit} characters. false lets CloudFormation generate "
            "the names, so plain CAPABILITY_IAM is enough, long stack names remain "
            "deployable, and account naming rules are not violated."
        )
    return limit


def _find_policy_statement(template: dict, role_id: str, sid: str) -> dict:
    """Find one inline statement by Sid, failing closed if the template drifted."""
    role = template.get("Resources", {}).get(role_id, {})
    for policy in role.get("Properties", {}).get("Policies", []):
        for statement in policy.get("PolicyDocument", {}).get("Statement", []):
            if statement.get("Sid") == sid:
                return statement
    raise CfnExportUnsupportedError(
        f"The naming profile could not update {role_id}/{sid}; the generated IAM policy "
        "shape changed and exporting names without their matching grants would be unsafe."
    )


def _rewrite_cedar_target_names(statement, target_names: dict[str, str]):
    """Move Cedar action ids with their renamed GatewayTarget resources.

    Generated statements are already ``Fn::Sub`` expressions, so replacing the
    literal target prefix in their string is sufficient. Caller-supplied Cedar is
    deliberately a plain string. Turning that whole value into ``Fn::Sub`` would
    make any ``${...}`` text the caller wrote become CloudFormation syntax. Build
    an ``Fn::Join`` instead: only the new target name is an intrinsic, and every
    byte of the caller's surrounding statement stays literal.
    """

    replacements = {old: new for old, new in target_names.items() if old != new}
    if not replacements:
        return statement

    targets = "|".join(re.escape(target) for target in sorted(replacements, key=len, reverse=True))
    action_target = re.compile(
        rf'(?P<prefix>(?:AgentCore\s*::\s*)?Action\s*::\s*")'
        rf"(?P<target>{targets})(?=___)"
    )

    def replace_generated(text: str) -> str:
        return action_target.sub(
            lambda match: match.group("prefix") + replacements[match.group("target")],
            text,
        )

    if isinstance(statement, dict) and "Fn::Sub" in statement:
        substitution = statement["Fn::Sub"]
        if isinstance(substitution, str):
            return {"Fn::Sub": replace_generated(substitution)}
        if isinstance(substitution, list) and len(substitution) == 2 and isinstance(substitution[0], str):
            return {
                "Fn::Sub": [
                    replace_generated(substitution[0]),
                    substitution[1],
                ]
            }
        raise CfnExportUnsupportedError(
            "A naming profile could not update a generated Cedar statement because its Fn::Sub shape is not supported."
        )

    if not isinstance(statement, str):
        raise CfnExportUnsupportedError(
            "A naming profile could not update a Cedar statement whose value is "
            f"{type(statement).__name__}; use a string policy statement."
        )

    # A caller's statement may quote an action id inside a ``// ...`` comment as
    # documentation; renaming its target there would silently rewrite the
    # customer's own words. Only rewrite matches that fall in the code runs — the
    # same comment-awareness the migration and served-action validation use.
    comment_spans: list[tuple[int, int]] = []
    pos = 0
    for text, is_comment in CfnTemplateGenerator._cedar_segments(statement):
        if is_comment:
            comment_spans.append((pos, pos + len(text)))
        pos += len(text)

    def _in_comment(index: int) -> bool:
        return any(start <= index < end for start, end in comment_spans)

    matches = [m for m in action_target.finditer(statement) if not _in_comment(m.start())]
    if not matches:
        return statement

    parts: list = []
    cursor = 0
    for match in matches:
        parts.append(statement[cursor : match.start("target")])
        parts.append({"Fn::Sub": replacements[match.group("target")]})
        cursor = match.end("target")
    parts.append(statement[cursor:])
    return {"Fn::Join": ["", parts]}


def _apply_naming_profile(template: dict, profile: CfnNamingProfile | None) -> None:
    """Apply customer names and every coupled reference in one fail-closed pass."""
    if profile is None:
        return

    unknown = sorted(set(profile.resource_names) - set(_NAMING_PROFILE_TEMPLATES))
    if unknown:
        raise CfnExportUnsupportedError(
            "namingProfile.resourceNames contains unknown resource families: "
            + ", ".join(unknown)
            + ". Supported families are: "
            + ", ".join(sorted(_NAMING_PROFILE_TEMPLATES))
        )

    # Validate even overrides for components this particular canvas does not emit.
    # Otherwise a saved profile appears valid on a runtime-only export and fails only
    # months later when the customer adds the component it misspelled.
    for key in sorted(_NAMING_PROFILE_TEMPLATES):
        _render_profile_name(profile, key)

    resources = template.get("Resources", {})

    def set_name(logical_id: str, property_name: str, key: str, **values) -> str | None:
        resource = resources.get(logical_id)
        if resource is None:
            return None
        rendered = _render_profile_name(profile, key, **values)
        resource.setdefault("Properties", {})[property_name] = {"Fn::Sub": rendered}
        return rendered

    # DeploymentName stays the variable part and is still overrideable at deploy
    # time. Twenty characters is the common denominator across AgentCore's 48-char
    # underscore names once a 12-char customer prefix and semantic suffix are added.
    deployment_parameter = template["Parameters"]["DeploymentName"]
    deployment_parameter.update(
        {
            "Default": _profile_deployment_default(str(deployment_parameter.get("Default", "agentcore"))),
            "MaxLength": 20,
            "AllowedPattern": "^[a-z][a-z0-9]{0,19}$",
            "ConstraintDescription": (
                "Lowercase alphanumeric only, no hyphens/underscores, 1-20 chars, "
                "must start with a letter. The 20-character ceiling keeps every "
                "profile-derived AgentCore name within its service limit."
            ),
            "Description": ("Variable part of the customer naming profile (lowercase alphanumeric, 1-20 characters)"),
        }
    )

    gateway_scope: str | None = None
    mcp_scope: str | None = None

    if "CognitoUserPool" in resources:
        set_name("CognitoUserPool", "UserPoolName", "cognitoUserPool")
        resource_server = _render_profile_name(profile, "cognitoResourceServer")
        for prop in ("Identifier", "Name"):
            resources["CognitoResourceServer"]["Properties"][prop] = {"Fn::Sub": resource_server}
        resources["CognitoUserPoolDomain"]["Properties"]["Domain"] = _profile_cognito_domain(profile, "cognitoDomain")
        set_name("CognitoUserPoolClient", "ClientName", "cognitoClient")
        gateway_scope = resource_server + "/invoke"
        resources["CognitoUserPoolClient"]["Properties"]["AllowedOAuthScopes"] = [{"Fn::Sub": gateway_scope}]

    gateway_name = set_name("AgentCoreGateway", "Name", "gateway")
    if gateway_name is not None:
        _find_policy_statement(template, "GatewayRole", "AgentCoreGatewayOps")["Resource"] = _agentcore_named_resources(
            f"gateway/{gateway_name}-*"
        )

    target_name_rewrites: dict[str, str] = {}
    for logical_id, target in sorted(resources.items()):
        if target.get("Type") != "AWS::BedrockAgentCore::GatewayTarget":
            continue
        properties = target.setdefault("Properties", {})
        old_name = properties.get("Name")
        if not isinstance(old_name, str):
            raise CfnExportUnsupportedError(
                f"The naming profile could not update {logical_id}; its GatewayTarget "
                "Name is no longer a literal string."
            )
        new_name = _render_profile_name(
            profile,
            "gatewayTarget",
            component=old_name,
        )
        properties["Name"] = {"Fn::Sub": new_name}
        target_name_rewrites[old_name] = new_name

    gateway_lambda_ids: set[str] = set()
    for target in resources.values():
        if target.get("Type") != "AWS::BedrockAgentCore::GatewayTarget":
            continue
        lambda_arn = (
            target.get("Properties", {})
            .get("TargetConfiguration", {})
            .get("Mcp", {})
            .get("Lambda", {})
            .get("LambdaArn", {})
            .get("Fn::GetAtt")
        )
        if isinstance(lambda_arn, list) and lambda_arn:
            gateway_lambda_ids.add(lambda_arn[0])

    for logical_id in sorted(gateway_lambda_ids):
        if logical_id == "KBToolLambda":
            key = "knowledgeBaseToolLambda"
            component = None
        elif logical_id.startswith("CustomTool") and logical_id.endswith("Lambda"):
            key = "customToolLambda"
            component = logical_id[len("CustomTool") : -len("Lambda")].lower()
        else:
            key = "toolLambda"
            component = logical_id.removesuffix("Lambda").lower()
        set_name(logical_id, "FunctionName", key, component=component)

    if gateway_lambda_ids:
        lambda_arns = []
        for logical_id in sorted(gateway_lambda_ids):
            fn_name = resources[logical_id]["Properties"]["FunctionName"]["Fn::Sub"]
            lambda_arns.append(
                {"Fn::Sub": (f"arn:${{AWS::Partition}}:lambda:${{AWS::Region}}:${{AWS::AccountId}}:function:{fn_name}")}
            )
        _find_policy_statement(template, "GatewayRole", "LambdaInvoke")["Resource"] = lambda_arns

    set_name("BedrockKnowledgeBase", "Name", "knowledgeBase")
    set_name("KBDataSource", "Name", "knowledgeBaseDataSource")
    if "KBVectorBucket" in resources:
        resources["KBVectorBucket"]["Properties"]["VectorBucketName"] = _profile_stack_unique_name(
            profile, "vectorBucket"
        )
    set_name("KBVectorIndex", "IndexName", "vectorIndex")

    memory_name = set_name("AgentCoreMemory", "Name", "memory")
    if memory_name is not None:
        memory_resources = _agentcore_named_resources(f"memory/{memory_name}-*")
        _find_policy_statement(template, "MemoryExecutionRole", "MemoryDataPlane")["Resource"] = memory_resources
        _find_policy_statement(template, "MemoryExecutionRole", "MemoryControlPlane")["Resource"] = (
            _agentcore_named_resources(f"memory/{memory_name}-*")
        )

    set_name("PolicyEngine", "Name", "policyEngine")
    for logical_id, policy in sorted(resources.items()):
        if policy.get("Type") != "Custom::AgentCorePolicy":
            continue
        properties = policy.setdefault("Properties", {})
        old_name = properties.get("Name")
        if not isinstance(old_name, str):
            raise CfnExportUnsupportedError(
                f"The naming profile could not update {logical_id}; its policy Name is no longer a literal string."
            )
        properties["Name"] = {
            "Fn::Sub": _render_profile_name(
                profile,
                "policy",
                component=old_name,
            )
        }
        properties["Statement"] = _rewrite_cedar_target_names(
            properties.get("Statement"),
            target_name_rewrites,
        )

    if "McpCognitoUserPool" in resources:
        set_name("McpCognitoUserPool", "UserPoolName", "mcpCognitoUserPool")
        mcp_resource_server = _render_profile_name(profile, "mcpCognitoResourceServer")
        for prop in ("Identifier", "Name"):
            resources["McpCognitoResourceServer"]["Properties"][prop] = {"Fn::Sub": mcp_resource_server}
        resources["McpCognitoDomain"]["Properties"]["Domain"] = _profile_cognito_domain(profile, "mcpCognitoDomain")
        set_name("McpCognitoClient", "ClientName", "mcpCognitoClient")
        mcp_scope = mcp_resource_server + "/invoke"
        resources["McpCognitoClient"]["Properties"]["AllowedOAuthScopes"] = [{"Fn::Sub": mcp_scope}]

    set_name("McpServerRuntime", "AgentRuntimeName", "mcpRuntime")
    mcp_endpoint_name = set_name("McpServerEndpoint", "Name", "mcpEndpoint")
    set_name("McpOAuth2CredentialProvider", "ProviderName", "mcpCredentialProvider")
    if mcp_scope and "McpServerGatewayTarget" in resources:
        oauth = resources["McpServerGatewayTarget"]["Properties"]["CredentialProviderConfigurations"][0][
            "CredentialProvider"
        ]["OauthCredentialProvider"]
        oauth["Scopes"] = [{"Fn::Sub": mcp_scope}]

    set_name("OnlineEvaluation", "OnlineEvaluationConfigName", "evaluation")
    set_name("BedrockGuardrail", "Name", "guardrail")
    set_name("AgentCoreRuntime", "AgentRuntimeName", "runtime")
    endpoint_name = set_name("RuntimeEndpoint", "Name", "runtimeEndpoint")

    if gateway_scope and "AgentCoreRuntime" in resources:
        resources["AgentCoreRuntime"]["Properties"]["EnvironmentVariables"]["COGNITO_SCOPE"] = {
            "Fn::Sub": gateway_scope
        }

    outputs = template.get("Outputs", {})
    if endpoint_name and "EndpointName" in outputs:
        outputs["EndpointName"]["Value"] = {"Fn::Sub": endpoint_name}
    if gateway_scope and "CognitoScope" in outputs:
        outputs["CognitoScope"]["Value"] = {"Fn::Sub": gateway_scope}
    if mcp_endpoint_name and "McpServerEndpointName" in outputs:
        outputs["McpServerEndpointName"]["Value"] = {"Fn::Sub": mcp_endpoint_name}

    role_keys = {
        "RuntimeExecutionRole": "runtimeRole",
        "GatewayRole": "gatewayRole",
        "ToolLambdaRole": "toolLambdaRole",
        "KBToolLambdaRole": "knowledgeBaseToolRole",
        "KnowledgeBaseRole": "knowledgeBaseRole",
        "MemoryExecutionRole": "memoryRole",
        "McpServerRole": "mcpRuntimeRole",
        "EvaluationRole": "evaluationRole",
    }
    for logical_id, key in role_keys.items():
        if logical_id in resources:
            resources[logical_id].setdefault("Properties", {})["RoleName"] = _profile_stack_unique_name(profile, key)

    effective = {
        key: profile.resource_names.get(key, default) for key, default in sorted(_NAMING_PROFILE_TEMPLATES.items())
    }
    template.setdefault("Metadata", {})["AgentCoreFlowsNamingProfile"] = {
        "Version": 1,
        "Prefix": profile.prefix,
        "EffectiveResourceNames": effective,
    }


def _naming_profile_readme(profile: CfnNamingProfile | None) -> str:
    if profile is None:
        return ""
    overrides = "\n".join(f"- `{key}`: `{value}`" for key, value in sorted(profile.resource_names.items()))
    override_text = overrides or "- No per-family overrides; the standard profile templates are used."
    return f"""

## Customer naming profile

This bundle was generated with the customer prefix `{profile.prefix}`. `DeploymentName`
is the variable part and accepts 1-20 lowercase alphanumeric characters. Hyphen-only AWS
families and underscore-only AgentCore families are rendered separately, so the same
profile remains valid across both naming grammars.

The generator derives IAM ARN patterns, OAuth scopes, runtime environment values, endpoint
outputs and governed log-group qualifiers from the same resolved names. Do not hand-edit
one of those surfaces independently. The effective profile is also recorded under
`Metadata.AgentCoreFlowsNamingProfile` in `template.yaml`.

Every per-family template must preserve the placeholders needed to prevent collisions:
`{{deployment}}` everywhere, `{{component}}` for component families, and `{{suffix}}`
for stack-unique domains, vector buckets, and IAM roles. If a user-controlled component
would exceed an AWS service limit, the generator keeps a readable prefix and appends a
stable hash rather than clipping two distinct names to the same value.

Overrides supplied for this bundle:

{override_text}
"""


# ---------------------------------------------------------------------------
# Source-code integrity
# ---------------------------------------------------------------------------

# The empty digest, i.e. content_digest({}). A parameter default of "" would let a
# deploy that skipped deploy.sh silently opt out of verification, so the default is
# always a real digest and the handler treats "" as "no digest given".
EMPTY_CONTENT_DIGEST = "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"


def content_digest(files: dict[str, str]) -> str:
    """Reproducible digest over a set of named source files.

    Hashes the file *contents*, not an archive of them: deploy.sh builds the zip
    with ``zip -r``, which embeds mtimes, so two zips of identical code differ
    while this value does not.

    The algorithm is duplicated in two other places on purpose — the generated
    deploy.sh recomputes it in bash from the local files, and the cfn-provider
    Lambda recomputes it in Python from the uploaded zip. All three must agree, so
    keep it boringly simple: one ``<name>  <sha256>`` line per file, sorted by
    name, hashed.
    """
    lines = "".join(f"{name}  {hashlib.sha256(body.encode()).hexdigest()}\n" for name, body in sorted(files.items()))
    return "sha256:" + hashlib.sha256(lines.encode()).hexdigest()


# ---------------------------------------------------------------------------
# Knowledge Base vector store
# ---------------------------------------------------------------------------

# Must match knowledge_base_step._build_storage_config's default. A mismatch does
# not fail the deploy — it creates an index the KB never queries, so retrieval
# silently returns nothing.
DEFAULT_VECTOR_INDEX_NAME = "bedrock-knowledge-base-default-index"

# AWS::S3Vectors::Index requires an explicit Dimension, and it MUST equal the
# embedding model's output width or ingestion fails at the first vector write.
# The live path hardcodes 1024 because it only ever ran Titan v2; a template the
# customer edits is more likely to see another model, so map the ones Bedrock
# offers for knowledge bases.
EMBEDDING_MODEL_DIMENSIONS: dict[str, int] = {
    "amazon.titan-embed-text-v1": 1536,
    "amazon.titan-embed-text-v2:0": 1024,  # configurable 256/512/1024; 1024 is the default
    "amazon.titan-embed-image-v1": 1024,
    "cohere.embed-english-v3": 1024,
    "cohere.embed-multilingual-v3": 1024,
}
DEFAULT_EMBEDDING_DIMENSION = 1024


def _embedding_dimension(embedding_model_id: str) -> int:
    """Vector width for *embedding_model_id*, defaulting to 1024."""
    return EMBEDDING_MODEL_DIMENSIONS.get(embedding_model_id, DEFAULT_EMBEDDING_DIMENSION)


def _s3_vectors_is_stack_managed(kb_config: dict) -> bool:
    """True when the exported stack must create the vector bucket and index itself.

    The live Step Functions path calls s3vectors:CreateVectorBucket/CreateIndex
    before CreateKnowledgeBase (see knowledge_base_step, lessons Bug 145 —
    Bedrock does NOT auto-provision an S3 Vectors store, and a missing one
    surfaces as the misleading "unable to assume the given role"). A template has
    no imperative step, so it declares the two resources instead.
    """
    if kb_config.get("vectorStoreType", "s3_vectors") != "s3_vectors":
        return False
    return not kb_config.get("s3VectorsIndexArn") and not kb_config.get("s3VectorsBucketArn")


# The same recognition the generated agent's ``_a2a_agentcore_peer_arn`` performs, over
# again. It has to be: the emitted agent.py is standalone customer code and cannot import
# this package, so the logic exists twice by construction. What keeps the two from drifting
# is not this comment but a test that feeds one corpus of allowlist entries to BOTH — the
# real function here and the function inside a generated module — and asserts they agree.
# Drift here is not cosmetic: the grant would cover a different set of peers than the code
# actually signs for, which surfaces as an AccessDenied on the one peer the customer
# configured, on a stack with nothing wrong in it.
_A2A_RUNTIME_ARN_RE = re.compile(rf"^{_A2A_PEER_ARN}$")


def _a2a_peer_runtime_arns(a2a_config: dict | None) -> list[str]:
    """The AgentCore runtime ARNs on the canvas's A2A peer allowlist, in order.

    These are the only allowlist entries that need an IAM grant at all: a non-AgentCore
    A2A peer is reached over plain HTTPS and needs no AWS permission. Both spellings are
    recognised — the bare ARN, and the data-plane URL a peer runtime's own agent card
    advertises — under the same truncation ``a2a_codegen`` applies when it bakes the
    allowlist into agent.py, so the parameter default cannot name a peer the baked
    allowlist dropped.

    Deduplicated, because an allowlist naming one runtime both ways would otherwise put it
    in the policy's Resource list twice.
    """
    peer_config = a2a_config or {}
    raw = peer_config.get("peer_allowlist") or peer_config.get("peerAllowlist") or []
    arns: list[str] = []
    for entry in [str(u)[:512] for u in raw][:64]:
        arn = _a2a_agentcore_runtime_arn(entry)
        if arn is not None and arn not in arns:
            arns.append(arn)
    return arns


def _a2a_grant_resources(peer_arns: list[str]) -> list[str]:
    """Every ARN the IAM grant must name so that ``InvokeAgentRuntime`` on a peer succeeds.

    Two per peer, and that is a measured fact rather than a belt-and-braces choice.
    ``InvokeAgentRuntime`` authorizes against the runtime ARN *and* the endpoint ARN the
    qualifier resolves to, so a grant naming only the runtime ARN — which is what this
    export emitted first — is denied ``on resource: <arn>/runtime-endpoint/DEFAULT``, and a
    grant naming only the endpoint ARN is denied ``on resource: <arn>``. Each is refused
    naming the resource the other had. The export could not call a peer at all.

    ``DEFAULT`` and not ``/runtime-endpoint/*``: the generated tool sends no qualifier, an
    omitted qualifier resolves to DEFAULT, so DEFAULT is the only endpoint it can reach and
    a wildcard would grant endpoints it cannot use. Keeping the wildcard out is also what
    lets ``A2A_PEER_ARNS_PATTERN`` go on rejecting a ``*``.

    An entry that already names an endpoint still yields two resources, the runtime ARN and
    that endpoint: keeping only the endpoint would reproduce exactly the failure above, and
    appending a second ``/runtime-endpoint/`` would produce an ARN matching nothing. So the
    endpoint is preserved and the runtime ARN it belongs to is added beside it.
    """
    resources: list[str] = []
    for arn in peer_arns:
        runtime, _, endpoint = arn.partition("/runtime-endpoint/")
        for resource in (runtime, f"{runtime}/runtime-endpoint/{endpoint or 'DEFAULT'}"):
            if resource not in resources:
                resources.append(resource)
    return resources


def _a2a_agentcore_runtime_arn(entry: str) -> str | None:
    """The runtime ARN ``entry`` names, whether written as an ARN or a data-plane URL."""
    candidate = (entry or "").strip()
    if candidate.startswith("arn:"):
        return candidate if _A2A_RUNTIME_ARN_RE.fullmatch(candidate) else None
    parsed = urllib.parse.urlparse(candidate)
    host = (parsed.hostname or "").lower()
    # Prefix AND suffix, so `bedrock-agentcore.us-east-1.amazonaws.com.evil.net` is not an
    # AgentCore endpoint. It would only ever mean a *narrower* grant here, but the same
    # check guards an unsigned POST in the generated agent and the two must agree.
    if not host.startswith("bedrock-agentcore.") or not host.endswith(".amazonaws.com"):
        return None
    segments = [s for s in parsed.path.split("/") if s]
    if len(segments) < 2 or segments[0] != "runtimes":
        return None
    # ``fullmatch`` rather than ``match``: Python's trailing dollar also matches just before
    # a newline at the end of the string, so ``match`` accepts an ARN with a trailing
    # newline, and this branch url-decodes a path segment — a peer url whose segment ends in
    # the percent-encoded form of a newline reached it, and the newline-bearing ARN went into
    # ``A2APeerRuntimeArns``'s Default.
    #
    # What that did NOT do, measured rather than assumed, and an earlier version of this
    # comment had it wrong: CloudFormation does not refuse such a value. It *trims* leading
    # and trailing whitespace before evaluating ``AllowedPattern``, so the change set was
    # accepted and the stored value came back without the newline — uniformly for ``\n``,
    # ``\r\n``, ``\n\n``, a space and a tab, and for a leading newline too. A whitespace-only
    # value is trimmed to empty, which makes the condition false and leaves the statement
    # absent. So on this side the defect was invisible, which is precisely why ``match``
    # survived here: normalization downstream hid it. An *embedded* newline is not trimmed and
    # is rejected, so no wildcard or second entry could be smuggled past the pattern either.
    #
    # The reason to full-match is therefore not a deploy-time failure. It is that the same
    # recognition runs a second time in the generated agent, where nothing trims: there the
    # newline-bearing string is what gets passed to ``invoke_agent_runtime``, and the two
    # copies must agree on what an ARN is. ARCC guidance on regex validation of multiline
    # input (cnt_QQz2pERJ9yvemV) is this exact shape — an ARN pattern anchored with a dollar,
    # where the remedy is to validate the entire input — and it holds on its own terms
    # regardless of what CloudFormation happens to normalize.
    arn = urllib.parse.unquote(segments[1])
    return arn if _A2A_RUNTIME_ARN_RE.fullmatch(arn) else None


# ---------------------------------------------------------------------------
# LiteLLM gateway provider
# ---------------------------------------------------------------------------

# A Secrets Manager secret ARN. Secrets Manager appends a 6-character random
# suffix to the name, and both the suffixed and unsuffixed forms are accepted by
# the API, so the length of the tail stays loose -- but its ALPHABET does not.
#
# The tail used to be `.+`, which is how a canvas ARN reading
# `:secret:evil$(printf SHELL_INJECTION)` passed this check and reached a
# double-quoted `echo` in the generated deploy.sh, where bash substituted it on
# execution. The alphabet below is Secrets Manager's own documented one for a
# secret name -- ASCII letters, digits and `/_+=.@-` -- which contains no shell
# metacharacter, no quote and no whitespace. 512 is the service's name limit.
#
# This is defence in depth, not the fix: the fix is that the value is rendered as a
# shell literal (see _shell_literal). A validator has to be right about every input
# anyone will ever paste on a canvas; the rendering does not.
SECRETSMANAGER_ARN_PATTERN = (
    r"^arn:aws[a-zA-Z-]*:secretsmanager:[a-z0-9-]{1,32}:[0-9]{12}:secret:[A-Za-z0-9/_+=.@-]{1,512}$"
)

# https only. The virtual key rides this connection on every MCP call, so a
# template that could be pointed at http:// by overriding a parameter would let
# anyone who can run a stack update downgrade the transport. The AllowedPattern
# on LiteLLMGatewayUrl enforces the same thing at deploy time.
#
# The excluded characters are the ones RFC 3986 does not allow in a URI at all:
# whitespace, the quotes, backtick, backslash, and `<>{}|^`. `$` and the brackets
# stay legal because they are RFC sub-delims and appear in real proxy URLs -- which
# is the point of _shell_literal: this URL reaches template.yaml and README.md and
# no script, and its safety there must not depend on guessing which characters a
# future sink would find dangerous.
LITELLM_URL_PATTERN = r"^https://[^\s\"'`<>\\{}|^]+$"

# A LiteLLM MCP server alias, e.g. `github` or `zapier_mcp`. Pinned aliases become
# the `x-mcp-servers` request header in the generated agent, and an embedded newline
# in a header value is rejected by every HTTP client we could be running on -- so an
# unconstrained alias exports a stack that deploys and then fails every tool call.
# Refused at export instead, where the message can name the alias.
LITELLM_SERVER_ALIAS_PATTERN = r"^[A-Za-z0-9._-]{1,128}$"
# The same rule for the comma-joined LiteLLMMcpServers parameter. Empty is valid:
# it means "every server this key can see".
LITELLM_SERVERS_PATTERN = r"^([A-Za-z0-9._-]{1,128}(,[A-Za-z0-9._-]{1,128})*)?$"


def _litellm_export_settings(gateway_config: dict | None) -> dict:
    """What the exported stack needs in order to talk to a customer's LiteLLM proxy.

    Reads both spellings of every key: the canvas sends camelCase and the stored
    form is snake_case (``resolve_gateway_provider`` carries the same pairs for
    the same reason).

    The virtual key itself is deliberately NOT in the result. ARCC guidance on
    customer-provided secrets (``cnt_77BHvX7WzuG1X8``) is explicit that a service
    must never ask a customer to supply a credential through CloudFormation and
    must accept a Secrets Manager ARN instead, so an inline ``litellm_api_key``
    left on the canvas is dropped here rather than written into the export. A
    template is a file people commit to git, paste into tickets and forward to
    colleagues; a key in it is a key that has leaked.
    """
    cfg = gateway_config or {}
    base_url = str(cfg.get("litellm_base_url") or cfg.get("litellmBaseUrl") or "").strip()
    if not base_url:
        raise CfnExportUnsupportedError(
            "This agent's gateway uses the LiteLLM provider but names no proxy base "
            "URL, so there is nothing to point the exported stack at. Set the LiteLLM "
            "base URL on the gateway node and export again."
        )
    # Scheme check only. The live path additionally resolves the hostname and
    # rejects private/IMDS addresses, because it actually connects to the proxy
    # from the control plane; the export only writes the URL into a document. A
    # private base URL is legitimate here — the customer may deploy this stack
    # inside the VPC that can reach it — so refusing it would be wrong.
    #
    # fullmatch, not match, for the same reason the A2A ARN above uses it: `$` in a
    # non-MULTILINE pattern also matches before a trailing newline, so `match` with a
    # trailing `$` accepts a value with junk after it in more cases than it looks like
    # it does. Every anchored validator in this module full-matches.
    if not re.fullmatch(LITELLM_URL_PATTERN, base_url):
        raise CfnExportUnsupportedError(
            f"The LiteLLM base URL {base_url!r} is not an https URL. The exported "
            "runtime sends your virtual key to this URL on every request, so only "
            "https is accepted, and a URL may not contain quotes, backticks, "
            "backslashes, whitespace or <>{}|^. Fix the base URL on the gateway node "
            "and export again."
        )

    servers = cfg.get("litellm_servers") or cfg.get("litellmServers") or []
    if isinstance(servers, str):
        servers = [s.strip() for s in servers.split(",") if s.strip()]
    servers = [str(s).strip() for s in servers if str(s).strip()]
    # Refused rather than dropped, unlike the key reference below: silently dropping a
    # pinned server would widen the export's scope to every server the key can see,
    # which is the opposite of what the canvas asked for. The alias is not a secret,
    # so the message names it.
    for alias in servers:
        if not re.fullmatch(LITELLM_SERVER_ALIAS_PATTERN, alias):
            raise CfnExportUnsupportedError(
                f"The LiteLLM MCP server alias {alias!r} is not a valid alias. An "
                "alias may contain letters, digits, dots, underscores and hyphens "
                "only, because it is sent as an HTTP header on every tool call. Fix "
                "the pinned servers on the gateway node and export again."
            )

    # An ARN from an earlier live deploy of the same canvas becomes the parameter
    # default, so a customer who deployed through the platform first does not have
    # to re-enter it. Absent, the parameter has no default and CloudFormation
    # requires a value — which is the correct failure: this stack cannot work
    # without a key, and a placeholder default would produce a stack that deploys
    # and then 401s on every tool call.
    secret_arn = str(cfg.get("litellm_api_key_ref") or cfg.get("litellmApiKeyRef") or "").strip()
    if secret_arn and not re.fullmatch(SECRETSMANAGER_ARN_PATTERN, secret_arn):
        # Not fatal: drop it and let the operator supply one. Baking an
        # unrecognized string in as a default would fail the deploy on a pattern
        # mismatch with no hint of where the value came from.
        logger.warning("Ignoring a stored LiteLLM key reference that is not a Secrets Manager ARN")
        empty_reference = ""
        secret_arn = empty_reference

    return {
        "base_url": base_url,
        "mcp_url": resolve_mcp_url(base_url, servers),
        "servers": servers,
        "secret_arn": secret_arn,
    }


